INSERT INTO _n1_b8_guard_0123(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2027-01-07' AND '2027-01-20' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3281','2027-01-07','体系','たいけい','체계; 서로 관련된 요소가 일정한 원리에 따라 조직된 전체','互いに関係する要素が、一定の原理に基づいて組織されたまとまり。','複雑な制度を理解するには、知識を体系として捉える必要がある。','복잡한 제도를 이해하려면 지식을 체계로 파악할 필요가 있다.'),
('n1-3282','2027-01-07','素質','そしつ','소질; 타고난 성질이나 잠재 능력','生まれつき備わっている性質や、将来伸びる可能性のある能力。','経験は浅いが、指導者としての素質は十分にある。','경험은 부족하지만 지도자로서의 소질은 충분히 있다.'),
('n1-3283','2027-01-07','超過','ちょうか','초과; 정해진 한도나 수량을 넘어섬','定められた限度や数量を超えること。','予算を超過しないよう、支出を毎月確認している。','예산을 초과하지 않도록 지출을 매달 확인하고 있다.'),
('n1-3284','2027-01-07','通用','つうよう','통용; 널리 받아들여져 사용됨; 효력이 있음','広く受け入れられて使われること、または効力を持つこと。','その説明は専門家には通用しても、一般の利用者には分かりにくい。','그 설명은 전문가에게는 통할지 몰라도 일반 이용자에게는 이해하기 어렵다.'),
('n1-3285','2027-01-07','標準','ひょうじゅん','표준; 판단이나 측정의 기준이 되는 것','判断や測定の基準となるもの、または一般的な水準。','安全性を確保するため、国際標準に沿って設計した。','안전성을 확보하기 위해 국제 표준에 따라 설계했다.'),
('n1-3286','2027-01-07','消化','しょうか','소화; 음식물을 흡수 가능한 상태로 만듦; 내용을 충분히 이해함','食物を吸収できる状態にすること。また、知識などを十分に理解すること。','大量の資料を短期間で消化するには、要点を見極める必要がある。','많은 자료를 단기간에 소화하려면 핵심을 가려낼 필요가 있다.'),
('n1-3287','2027-01-07','作製','さくせい','제작; 기계나 도구 같은 물건을 실제로 만듦','機械・器具・標本などの物品を実際に作ること。','実験条件に合わせて専用の測定装置を作製した。','실험 조건에 맞춰 전용 측정 장치를 제작했다.'),
('n1-3288','2027-01-07','住居','じゅうきょ','주거; 사람이 생활하는 집이나 장소','人が日常生活を営む家や場所。','災害後、住居を失った人への支援が急がれた。','재해 후 주거를 잃은 사람들에 대한 지원이 시급했다.'),
('n1-3289','2027-01-07','資料','しりょう','자료; 조사·연구·판단의 근거가 되는 정보나 문서','調査・研究・判断の材料となる情報や文書。','複数の資料を照合し、記述の正確性を確認した。','여러 자료를 대조하여 서술의 정확성을 확인했다.'),
('n1-3290','2027-01-07','心身','しんしん','심신; 마음과 몸','心と身体。','長時間の勤務は心身に大きな負担を及ぼす。','장시간 근무는 심신에 큰 부담을 준다.'),
('n1-3291','2027-01-07','申請','しんせい','신청; 허가나 처리를 공식적으로 요청함','許可や手続きなどを公的な機関に申し出ること。','補助金を受けるには期限内に申請する必要がある。','보조금을 받으려면 기한 안에 신청해야 한다.'),
('n1-3292','2027-01-07','診断','しんだん','진단; 상태를 조사하여 질병이나 문제의 원인을 판단함','状態を調べ、病気や問題の原因・性質を判断すること。','専門家が設備を診断し、故障の原因を特定した。','전문가가 설비를 진단해 고장 원인을 특정했다.'),
('n1-3293','2027-01-07','人命','じんめい','인명; 사람의 생명','人の生命。','人命を最優先に考え、直ちに避難を開始した。','인명을 최우선으로 생각해 즉시 대피를 시작했다.'),
('n1-3294','2027-01-07','推定','すいてい','추정; 알려진 사실을 바탕으로 수치나 상태를 미루어 판단함','分かっている事実を基に、数量や状態を推し量ること。','限られた資料から当時の人口を推定した。','제한된 자료를 바탕으로 당시 인구를 추정했다.'),
('n1-3295','2027-01-07','製作','せいさく','제작; 기계·제품·도구 등을 만듦','機械・製品・道具などを作ること。','設計図を基に試作品を製作し、耐久性を調べた。','설계도를 바탕으로 시제품을 제작해 내구성을 조사했다.'),
('n1-3296','2027-01-07','生存','せいぞん','생존; 살아남아 존재함','生きて存在し続けること。','厳しい環境で生存するために独自の機能が発達した。','가혹한 환경에서 생존하기 위해 독자적인 기능이 발달했다.'),
('n1-3297','2027-01-07','政党','せいとう','정당; 정치적 목표를 함께하는 사람들이 만든 조직','共通の政治的目標を持つ人々が組織する団体。','各政党が経済政策について異なる方針を示した。','각 정당이 경제 정책에 관해 서로 다른 방침을 제시했다.'),
('n1-3298','2027-01-07','整備','せいび','정비; 시설이나 제도를 갖추고 제대로 기능하게 함','施設や制度を整え、十分に機能する状態にすること。','地域医療の体制を整備するため、新たな拠点を設けた。','지역 의료 체계를 정비하기 위해 새로운 거점을 마련했다.'),
('n1-3299','2027-01-07','成分','せいぶん','성분; 물질을 구성하는 요소','物質や混合物を構成している要素。','製品に含まれる成分を分析し、安全性を確認した。','제품에 포함된 성분을 분석해 안전성을 확인했다.'),
('n1-3300','2027-01-07','成立','せいりつ','성립; 조건이 갖추어져 제도·계약·관계 등이 이루어짐','必要な条件が整い、制度・契約・関係などが成り立つこと。','双方が条件に合意し、契約が正式に成立した。','양측이 조건에 합의하여 계약이 정식으로 성립했다.'),
('n1-3301','2027-01-08','接近','せっきん','접근; 가까이 다가감','対象の近くへ寄ること、または距離が近づくこと。','大型の台風が沿岸部に接近している。','대형 태풍이 연안 지역에 접근하고 있다.'),
('n1-3302','2027-01-08','接続','せつぞく','접속; 둘 이상의 것을 이어 연결함','二つ以上のものをつないで連絡させること。','端末を社内ネットワークに接続して設定を更新した。','단말기를 사내 네트워크에 접속해 설정을 갱신했다.'),
('n1-3303','2027-01-08','先端','せんたん','선단; 맨 앞끝; 가장 앞선 분야','物のいちばん先の部分。また、技術や研究の最も進んだ領域。','この研究所では先端技術の実用化を進めている。','이 연구소에서는 첨단 기술의 실용화를 추진하고 있다.'),
('n1-3304','2027-01-08','宣伝','せんでん','선전; 널리 알리거나 지지를 얻기 위해 정보를 퍼뜨림','商品・活動・主張などを広く知らせること。','効果だけを強調して宣伝すると、利用者に誤解を与えかねない。','효과만 강조해 선전하면 이용자에게 오해를 줄 수 있다.'),
('n1-3305','2027-01-08','全般','ぜんぱん','전반; 어떤 범위의 전체','ある範囲の物事の全体。','制度全般を見直し、重複した手続きを削減した。','제도 전반을 재검토하여 중복된 절차를 줄였다.'),
('n1-3306','2027-01-08','相違','そうい','상위; 서로 같지 않고 차이가 있음','二つ以上のものの間に違いがあること。','報告書と実際の記録には重大な相違が見つかった。','보고서와 실제 기록 사이에서 중대한 차이가 발견되었다.'),
('n1-3307','2027-01-08','増減','ぞうげん','증감; 늘거나 줄어듦','数量が増えることと減ること。','利用者数の増減を月ごとに比較した。','이용자 수의 증감을 월별로 비교했다.'),
('n1-3308','2027-01-08','相互','そうご','상호; 양쪽이 서로 관계함','双方が互いに関係し合うこと。','相互の立場を理解することが合意形成の第一歩となる。','서로의 입장을 이해하는 것이 합의 형성의 첫걸음이 된다.'),
('n1-3309','2027-01-08','増大','ぞうだい','증대; 수량이나 정도가 크게 늘어남','数量や程度が大きく増えること。','需要の増大に伴い、供給体制の拡充が求められた。','수요 증대에 따라 공급 체계의 확충이 요구되었다.'),
('n1-3310','2027-01-08','測定','そくてい','측정; 기구나 기준을 이용해 수치로 나타냄','器具や基準を用いて量を測り、数値で示すこと。','同じ条件で温度を測定し、結果の差を比較した。','같은 조건에서 온도를 측정해 결과 차이를 비교했다.'),
('n1-3311','2027-01-08','損得','そんとく','손익; 손해와 이익','損失と利益、または損か得かということ。','目先の損得だけで公共政策を評価すべきではない。','눈앞의 손익만으로 공공 정책을 평가해서는 안 된다.'),
('n1-3312','2027-01-08','対立','たいりつ','대립; 의견이나 입장이 맞서 충돌함','意見や立場などが互いに反対し、ぶつかり合うこと。','両者の対立を解くには、争点を整理する必要がある。','양측의 대립을 풀려면 쟁점을 정리할 필요가 있다.'),
('n1-3313','2027-01-08','妥当','だとう','타당; 판단이나 방법이 상황에 알맞고 합리적임','判断や方法が状況に合っており、合理的であること。','その結論が妥当かどうか、別の資料でも検証した。','그 결론이 타당한지 다른 자료로도 검증했다.'),
('n1-3314','2027-01-08','段階','だんかい','단계; 진행 과정에서 구분되는 순서나 수준','物事の進行過程で区切られる順序や程度。','計画を段階に分け、結果を確認しながら進めた。','계획을 단계별로 나누어 결과를 확인하며 진행했다.'),
('n1-3315','2027-01-08','断定','だんてい','단정; 충분한 여지를 두지 않고 확실하다고 판단함','物事をはっきりそうだと決めつけること。','証拠が不十分な段階で原因を断定するのは危険だ。','증거가 불충분한 단계에서 원인을 단정하는 것은 위험하다.'),
('n1-3316','2027-01-08','中途','ちゅうと','중도; 일이 진행되는 도중','物事が進行している途中。','計画を中途で変更したため、追加の説明が必要になった。','계획을 중도에 변경해서 추가 설명이 필요해졌다.'),
('n1-3317','2027-01-08','調整','ちょうせい','조정; 상태나 관계를 알맞게 맞춤','状態や関係を整え、適切になるように合わせること。','関係部署と日程を調整し、実施日を決定した。','관련 부서와 일정을 조정하여 실시일을 결정했다.'),
('n1-3318','2027-01-08','貯蔵','ちょぞう','저장; 물품이나 자원을 보관해 둠','物品や資源を蓄えて保管すること。','収穫した穀物を適切な温度で貯蔵する。','수확한 곡물을 적절한 온도에서 저장한다.'),
('n1-3319','2027-01-08','分布','ぶんぷ','분포; 일정한 범위에 퍼져 있음','物事が一定の範囲に広がって存在すること。','調査結果を地図に示し、被害の分布を確認した。','조사 결과를 지도에 표시해 피해 분포를 확인했다.'),
('n1-3320','2027-01-08','利害','りがい','이해; 이익과 손해','利益と損害。','利害の異なる関係者から意見を聞き、合意点を探った。','이해관계가 다른 관계자들의 의견을 듣고 합의점을 찾았다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3321','2027-01-09','承る','うけたまわる','삼가 듣다; 받다; 맡다의 겸양 표현','「聞く・受ける・引き受ける」の謙譲語。','ご要望を承る窓口を新たに設けました。','요청 사항을 접수하는 창구를 새로 마련했습니다.'),
('n1-3322','2027-01-09','補う','おぎなう','보충하다; 부족한 부분을 채우다','不足している部分を付け加えて満たす。','不足するデータを追加調査で補う必要がある。','부족한 데이터를 추가 조사로 보충할 필요가 있다.'),
('n1-3323','2027-01-09','怠る','おこたる','게을리하다; 해야 할 일을 소홀히 하다','すべきことを十分に行わず、なおざりにする。','日常の点検を怠ると、重大な事故につながりかねない。','일상 점검을 게을리하면 중대한 사고로 이어질 수 있다.'),
('n1-3324','2027-01-09','改める','あらためる','고치다; 새롭게 바꾸다; 다시 확인하다','以前の状態を見直して変える。また、もう一度確かめる。','調査結果を踏まえ、従来の方針を改めることにした。','조사 결과를 바탕으로 기존 방침을 바꾸기로 했다.'),
('n1-3325','2027-01-09','著す','あらわす','저술하다; 책이나 글을 쓰다','書物や文章を書いて世に出す。','研究成果を専門書として著すことが彼の長年の目標だった。','연구 성과를 전문서로 저술하는 것이 그의 오랜 목표였다.'),
('n1-3326','2027-01-09','争う','あらそう','다투다; 경쟁하다; 사실 여부를 문제 삼다','相手と対立して競う。また、事実や権利について異議を唱える。','両社が新技術の主導権を争う構図になっている。','두 회사가 신기술 주도권을 다투는 구도가 되었다.'),
('n1-3327','2027-01-09','敬う','うやまう','공경하다; 존경하는 마음으로 대하다','相手を尊い存在として尊敬し、礼を尽くす。','異なる文化を敬う姿勢が相互理解につながる。','서로 다른 문화를 존중하는 태도가 상호 이해로 이어진다.'),
('n1-3328','2027-01-09','治める','おさめる','다스리다; 질서 있게 통치하다','国や地域を統治し、秩序ある状態にする。','国を治める者には公平な判断が求められる。','나라를 다스리는 사람에게는 공정한 판단이 요구된다.'),
('n1-3329','2027-01-09','傾く','かたむく','기울다; 한쪽 방향이나 상태로 치우치다','斜めになる。また、ある方向や状態へ偏る。','一方の意見に傾く前に、反対の根拠も確認すべきだ。','한쪽 의견으로 기울기 전에 반대 근거도 확인해야 한다.'),
('n1-3330','2027-01-09','兼ねる','かねる','겸하다; 두 가지 이상의 역할을 함께 맡다; 하기 어렵다','二つ以上の役割を同時に持つ。また、「〜かねる」で実行が難しいことを表す。','この施設は地域交流の場と災害時の避難所を兼ねる。','이 시설은 지역 교류 공간과 재해 시 대피소 역할을 겸한다.'),
('n1-3331','2027-01-09','刻む','きざむ','새기다; 잘게 썰다; 시간이나 변화를 차곡차곡 기록하다','細かく切る、文字などを彫る。また、時間や変化を積み重ねる。','地域の歴史を後世に刻むため、記録を保存した。','지역의 역사를 후세에 새기기 위해 기록을 보존했다.'),
('n1-3332','2027-01-09','崩す','くずす','무너뜨리다; 균형이나 형식을 깨뜨리다','まとまった形や均衡を壊す。','急な予定変更は生活のリズムを崩す原因になる。','갑작스러운 일정 변경은 생활 리듬을 흐트러뜨리는 원인이 된다.'),
('n1-3333','2027-01-09','崩れる','くずれる','무너지다; 균형이나 질서가 깨지다','まとまった形や均衡が壊れる。','前提が一つ変わるだけで、計画全体が崩れる可能性がある。','전제 하나만 바뀌어도 계획 전체가 무너질 가능성이 있다.'),
('n1-3334','2027-01-09','砕く','くだく','부수다; 잘게 깨다; 어려운 내용을 쉽게 풀다','固い物を細かく壊す。また、難しい内容を分かりやすくする。','専門用語を砕くように説明し、参加者の理解を助けた。','전문 용어를 쉽게 풀어 설명해 참가자들의 이해를 도왔다.'),
('n1-3335','2027-01-09','砕ける','くだける','부서지다; 딱딱한 태도나 표현이 부드러워지다','細かく壊れる。また、態度や表現が堅苦しくなくなる。','懇談が始まると、参加者の表情も次第に砕ける。','간담회가 시작되자 참가자들의 표정도 점차 부드러워진다.'),
('n1-3336','2027-01-09','悔やむ','くやむ','후회하다; 사람의 죽음을 애도하다','過ぎたことを残念に思う。また、人の死を悲しむ。','確認を怠ったことを後になって悔やむ人は少なくない。','확인을 소홀히 한 일을 나중에 후회하는 사람이 적지 않다.'),
('n1-3337','2027-01-09','削る','けずる','깎다; 일부를 줄이거나 없애다','表面を薄く取り除く。また、数量や内容の一部を減らす。','必要な機能を残しながら開発費を削る方法を検討した。','필요한 기능을 유지하면서 개발비를 줄이는 방법을 검토했다.'),
('n1-3338','2027-01-09','請う','こう','청하다; 상대에게 간절히 요구하거나 부탁하다','相手に何かを強く求めたり、願ったりする。','専門家の判断を請うため、資料を添えて意見を求めた。','전문가의 판단을 구하기 위해 자료를 첨부해 의견을 요청했다.'),
('n1-3339','2027-01-09','超える','こえる','넘다; 기준·수량·범위를 상회하다','基準・数量・範囲などを上回る。','応募者が定員を大幅に超える見込みだ。','지원자가 정원을 크게 넘을 전망이다.'),
('n1-3340','2027-01-09','遡る','さかのぼる','거슬러 올라가다; 과거의 시점까지 되짚다','流れと反対に上る。また、過去の時点までたどる。','記録を十年前まで遡ることで、問題の原因が見えてきた。','기록을 10년 전까지 거슬러 올라가자 문제의 원인이 보이기 시작했다.'),
('n1-3341','2027-01-10','探る','さぐる','탐색하다; 숨겨진 사정이나 가능성을 알아보다','見えない事情や可能性を調べて明らかにしようとする。','対話を重ねながら解決策を探る姿勢が重要だ。','대화를 거듭하며 해결책을 모색하는 자세가 중요하다.'),
('n1-3342','2027-01-10','囁く','ささやく','속삭이다; 작은 목소리로 말하다','相手に聞こえる程度の小さな声で話す。','周囲に聞こえないよう耳元で囁く声がした。','주변에 들리지 않도록 귓가에 속삭이는 소리가 났다.'),
('n1-3343','2027-01-10','妨げる','さまたげる','방해하다; 진행이나 실현을 가로막다','物事の進行や実現を邪魔する。','過度な手続きは迅速な支援を妨げる要因となる。','지나치게 복잡한 절차는 신속한 지원을 방해하는 요인이 된다.'),
('n1-3344','2027-01-10','縛る','しばる','묶다; 규칙이나 조건으로 자유를 제한하다','ひもなどで結ぶ。また、規則や条件によって自由を制限する。','細かい規則で現場の判断を縛るべきではない。','세세한 규칙으로 현장의 판단을 얽매어서는 안 된다.'),
('n1-3345','2027-01-10','絞る','しぼる','짜다; 범위나 대상을 좁히다','水分を押し出す。また、範囲や対象を限定する。','複数の案から実現可能な三案に候補を絞る。','여러 안 가운데 실현 가능한 세 가지로 후보를 좁힌다.'),
('n1-3346','2027-01-10','生ずる','しょうずる','생기다; 발생하다; 만들어 내다','新しい事態や結果が起こる、または生み出される。','制度の変更によって新たな負担が生ずる可能性がある。','제도 변경으로 새로운 부담이 생길 가능성이 있다.'),
('n1-3347','2027-01-10','接する','せっする','접하다; 맞닿다; 사람이나 정보와 마주하다','触れ合う、隣り合う。また、人や情報に向き合う。','多様な価値観に接することで、考え方の幅が広がった。','다양한 가치관을 접하면서 사고의 폭이 넓어졌다.'),
('n1-3348','2027-01-10','迫る','せまる','다가오다; 강하게 요구하다; 임박하다','距離や時期が近づく。また、強く要求する。','回答期限が迫る中、早急な判断が求められた。','답변 기한이 다가오는 가운데 신속한 판단이 요구되었다.'),
('n1-3349','2027-01-10','攻める','せめる','공격하다; 적극적으로 공략하다','相手を攻撃する。また、目標に対して積極的に働きかける。','守りに入るだけでなく、新しい市場を積極的に攻める方針だ。','방어에만 머무르지 않고 새로운 시장을 적극적으로 공략할 방침이다.'),
('n1-3350','2027-01-10','属する','ぞくする','속하다; 어떤 집단이나 범주에 포함되다','ある集団・組織・分類の中に含まれる。','この権限は地方自治体ではなく国に属する。','이 권한은 지방자치단체가 아니라 국가에 속한다.'),
('n1-3351','2027-01-10','逸れる','それる','벗어나다; 방향이나 주제에서 빗나가다','進むべき方向や本来の話題から外れる。','議論が本題から逸れるたびに、司会者が論点を戻した。','논의가 본론에서 벗어날 때마다 사회자가 쟁점을 되돌렸다.'),
('n1-3352','2027-01-10','揃う','そろう','갖추어지다; 전부 모이다; 서로 일치하다','必要なものが全部集まる。また、形や状態が一致する。','判断に必要な資料が揃うまで結論を保留した。','판단에 필요한 자료가 모두 갖추어질 때까지 결론을 보류했다.'),
('n1-3353','2027-01-10','揃える','そろえる','갖추다; 모으다; 같은 상태로 맞추다','必要なものを集める。また、形や条件を同じにする。','正確に比較するには調査条件を揃える必要がある。','정확하게 비교하려면 조사 조건을 맞출 필요가 있다.'),
('n1-3354','2027-01-10','高める','たかめる','높이다; 수준이나 정도를 향상시키다','水準や程度をより高くする。','情報公開を進め、行政への信頼を高める必要がある。','정보 공개를 추진하여 행정에 대한 신뢰를 높일 필요가 있다.'),
('n1-3355','2027-01-10','蓄える','たくわえる','저축하다; 지식·자원·힘 등을 모아 두다','金銭・知識・資源・力などを少しずつためておく。','将来の変化に備えて専門知識を蓄えることが大切だ。','미래의 변화에 대비해 전문 지식을 쌓는 것이 중요하다.'),
('n1-3356','2027-01-10','耕す','たがやす','경작하다; 땅을 갈다; 분야를 꾸준히 개척하다','農地を掘り返して作物を育てやすくする。転じて、分野を開拓する。','新しい研究分野を地道に耕す姿勢が成果につながった。','새로운 연구 분야를 꾸준히 개척하는 자세가 성과로 이어졌다.'),
('n1-3357','2027-01-10','誓う','ちかう','맹세하다; 굳게 약속하다','決意や約束を固く表明する。','同じ過ちを繰り返さないと誓うだけでなく、仕組みも改めた。','같은 잘못을 반복하지 않겠다고 맹세할 뿐 아니라 제도도 고쳤다.'),
('n1-3358','2027-01-10','縮む','ちぢむ','줄어들다; 길이·크기·기간 등이 작아지다','長さ・大きさ・期間などが小さくなる。','技術の進歩で処理時間が縮む一方、確認項目は増えている。','기술 발전으로 처리 시간은 줄지만 확인 항목은 늘고 있다.'),
('n1-3359','2027-01-10','縮める','ちぢめる','줄이다; 거리·시간·차이 등을 작게 만들다','距離・時間・差などを小さくする。','工程を見直し、納期を一週間縮めることができた。','공정을 재검토해 납기를 일주일 단축할 수 있었다.'),
('n1-3360','2027-01-10','通ずる','つうずる','통하다; 서로 이어지다; 어떤 분야에 정통하다','互いにつながる、意味が伝わる、またはある分野に詳しい。','異なる分野にも通ずる原理を見いだした。','서로 다른 분야에도 통하는 원리를 발견했다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3361','2027-01-11','味わう','あじわう','맛보다; 직접 경험하며 깊이 느끼다','飲食物の味を十分に感じる。また、経験や感情を深く感じ取る。','現地を訪れ、地域独自の文化を味わう機会を得た。','현지를 방문해 지역 고유의 문화를 체험할 기회를 얻었다.'),
('n1-3362','2027-01-11','預かる','あずかる','맡다; 보관하다; 책임지고 관리하다','人や物を引き受けて、責任を持って保管・管理する。','利用者の個人情報を預かる以上、厳重な管理が必要だ。','이용자의 개인정보를 맡는 이상 엄격한 관리가 필요하다.'),
('n1-3363','2027-01-11','暴れる','あばれる','난폭하게 굴다; 거세게 날뛰다','乱暴な行動をする。また、激しく動き回る。','災害時に群衆が暴れる事態を防ぐには、正確な情報提供が欠かせない。','재해 시 군중이 난폭하게 행동하는 사태를 막으려면 정확한 정보 제공이 필수적이다.'),
('n1-3364','2027-01-11','甘やかす','あまやかす','응석을 받아주다; 지나치게 관대하게 대하다','相手の要求を安易に受け入れ、厳しく接しない。','部下を甘やかすことと、失敗から学ぶ機会を与えることは違う。','부하의 응석을 받아주는 것과 실패에서 배울 기회를 주는 것은 다르다.'),
('n1-3365','2027-01-11','余る','あまる','남다; 필요량이나 한도를 넘다','必要な量を超えて残る。','予算が余るからといって、不要な支出を増やすべきではない。','예산이 남는다고 해서 불필요한 지출을 늘려서는 안 된다.'),
('n1-3366','2027-01-11','編む','あむ','뜨다; 엮다; 자료를 모아 책으로 만들다','糸などを組み合わせる。また、資料をまとめて書物を作る。','研究成果を一冊の事典に編む作業が進められている。','연구 성과를 한 권의 사전으로 엮는 작업이 진행되고 있다.'),
('n1-3367','2027-01-11','嫌がる','いやがる','싫어하다; 싫다는 태도를 보이다','嫌だと感じ、その気持ちを態度に表す。','本人が嫌がる方法を無理に押し付けてはいけない。','본인이 싫어하는 방법을 억지로 강요해서는 안 된다.'),
('n1-3368','2027-01-11','飢える','うえる','굶주리다; 필요한 것이 몹시 부족하다','食物がなく空腹に苦しむ。また、必要なものを強く求める。','紛争によって多くの住民が食料に飢える状況が続いている。','분쟁으로 많은 주민이 식량 부족에 시달리는 상황이 계속되고 있다.'),
('n1-3369','2027-01-11','浮かべる','うかべる','띄우다; 표정이나 생각을 드러내다; 떠올리다','水面などに浮かせる。また、表情に出したり心に思い描いたりする。','彼女は安堵の表情を浮かべると、静かに席を立った。','그녀는 안도하는 표정을 띠고 조용히 자리에서 일어났다.'),
('n1-3370','2027-01-11','浮く','うく','뜨다; 고정되지 않다; 주변과 어울리지 않다','水面や空中に上がる。また、周囲から離れて目立つ。','根拠のない提案は現場の実情から浮くおそれがある。','근거 없는 제안은 현장 실정과 동떨어질 우려가 있다.'),
('n1-3371','2027-01-11','薄める','うすめる','묽게 하다; 농도나 정도를 낮추다','液体の濃度や物事の程度を低くする。','薬品を規定の濃度まで水で薄める。','약품을 규정된 농도까지 물로 희석한다.'),
('n1-3372','2027-01-11','討つ','うつ','토벌하다; 공격하여 쓰러뜨리다','敵や悪者を攻めて倒す。','物語では、主人公が家族の敵を討つ旅に出る。','이야기에서 주인공은 가족의 원수를 갚기 위한 여행을 떠난다.'),
('n1-3373','2027-01-11','映す','うつす','비추다; 영상이나 모습을 화면에 나타내다','光や映像によって、物の姿を画面や鏡などに表す。','会場の様子を大型画面に映す設備を導入した。','행사장 모습을 대형 화면에 비추는 설비를 도입했다.'),
('n1-3374','2027-01-11','写る','うつる','찍히다; 사진이나 영상에 나타나다','写真や映像の中に姿が記録される。','資料の端に個人情報が写る可能性があるため確認が必要だ。','자료 가장자리에 개인정보가 찍힐 가능성이 있어 확인이 필요하다.'),
('n1-3375','2027-01-11','映る','うつる','비치다; 화면이나 눈에 모습이 나타나다','鏡・水面・画面・目などに姿や映像が現れる。','照明の色によって、同じ商品でも違って映る。','조명 색에 따라 같은 상품도 다르게 보인다.'),
('n1-3376','2027-01-11','埋める','うめる','묻다; 메우다; 부족한 부분을 채우다','土などの中に入れる。また、空白や不足を満たす。','地域間の情報格差を埋める取り組みが必要だ。','지역 간 정보 격차를 메우는 노력이 필요하다.'),
('n1-3377','2027-01-11','占う','うらなう','점을 치다; 징후를 통해 미래나 결과를 예측하다','兆候や方法に基づいて未来や運勢を判断する。','一度の調査だけで政策の成否を占うことはできない。','한 번의 조사만으로 정책의 성패를 점칠 수는 없다.'),
('n1-3378','2027-01-11','恨む','うらむ','원망하다; 부당한 일을 마음에 품다','害や不当な扱いを受けた相手に強い不満を抱く。','結果だけを見て担当者を恨むのではなく、判断の過程を調べるべきだ。','결과만 보고 담당자를 원망하지 말고 판단 과정을 조사해야 한다.'),
('n1-3379','2027-01-11','羨む','うらやむ','부러워하다; 남의 처지나 능력을 탐내다','他人の境遇や能力を見て、自分もそうなりたいと思う。','他人の成果を羨むより、自分の課題に集中した方がよい。','남의 성과를 부러워하기보다 자신의 과제에 집중하는 편이 낫다.'),
('n1-3380','2027-01-11','拝む','おがむ','절하다; 신불 앞에서 기도하다; 간절히 부탁하다','神仏などに手を合わせて祈る。また、強く頼み込む。','初日の出を拝むため、多くの人が山頂を目指した。','새해 첫 해돋이를 보기 위해 많은 사람이 산 정상을 향했다.'),
('n1-3381','2027-01-12','納める','おさめる','납부하다; 거두어 넣다; 일정한 자리에 수납하다','金銭や品物を所定の場所・相手に渡す。また、中にしまう。','期限までに税金を納める義務がある。','기한까지 세금을 납부할 의무가 있다.'),
('n1-3382','2027-01-12','驚かす','おどろかす','놀라게 하다','予想外の出来事などによって相手をびっくりさせる。','突然の方針転換は関係者を驚かす結果となった。','갑작스러운 방침 전환은 관계자들을 놀라게 했다.'),
('n1-3383','2027-01-12','卸す','おろす','도매로 넘기다; 새 물건을 처음 사용하다','商品を小売業者に売り渡す。また、新しい物を初めて使う。','生産者が商品を市場へ直接卸す仕組みを整えた。','생산자가 상품을 시장에 직접 도매로 넘기는 체계를 마련했다.'),
('n1-3384','2027-01-12','帰す','かえす','돌려보내다; 어떤 원인이나 책임으로 돌리다','元の場所へ帰らせる。また、原因や責任をあるものに求める。','問題の原因を個人の能力だけに帰すのは適切ではない。','문제의 원인을 개인 능력만으로 돌리는 것은 적절하지 않다.'),
('n1-3385','2027-01-12','代える','かえる','대신하게 하다; 다른 것으로 교체하다','あるものの役割を別のものにさせる。','対面会議をオンライン形式に代えることになった。','대면 회의를 온라인 형식으로 바꾸게 되었다.'),
('n1-3386','2027-01-12','掻く','かく','긁다; 휘저어 모으다','爪などで表面をこする。また、手や道具でかき集める。','傷口を掻くと症状が悪化するおそれがある。','상처 부위를 긁으면 증상이 악화될 우려가 있다.'),
('n1-3387','2027-01-12','嗅ぐ','かぐ','냄새를 맡다','鼻でにおいを感じ取る。','異臭を嗅ぐ場合は、直ちにその場を離れてください。','이상한 냄새를 맡으면 즉시 그 장소를 떠나십시오.'),
('n1-3388','2027-01-12','重なる','かさなる','겹치다; 여러 일이 동시에 일어나다','物や時期などが同じ位置・時間に集まる。','複数の要因が重なることで、被害が拡大した。','여러 요인이 겹치면서 피해가 확대되었다.'),
('n1-3389','2027-01-12','重ねる','かさねる','겹치다; 반복해서 쌓다','物を上に載せる。また、行為や経験を何度も繰り返す。','議論を重ねる中で、双方の立場の違いが明確になった。','논의를 거듭하는 가운데 양측의 입장 차이가 명확해졌다.'),
('n1-3390','2027-01-12','固まる','かたまる','굳다; 의견이나 방침이 확정되다','柔らかいものが硬くなる。また、意見や方針が決まる。','具体的な方針が固まるまで、発表は控えることにした。','구체적인 방침이 확정될 때까지 발표를 자제하기로 했다.'),
('n1-3391','2027-01-12','担ぐ','かつぐ','메다; 추켜세우다; 미신이나 장난에 속이다','肩に載せて運ぶ。また、人を持ち上げたり、だましたりする。','負傷者を担ぐ際は、首を動かさないよう注意する。','부상자를 멜 때는 목을 움직이지 않도록 주의한다.'),
('n1-3392','2027-01-12','被せる','かぶせる','씌우다; 덮다; 책임을 떠넘기다','上から覆うように載せる。また、責任などを他人に負わせる。','失敗の責任を現場だけに被せるべきではない。','실패의 책임을 현장에만 떠넘겨서는 안 된다.'),
('n1-3393','2027-01-12','枯れる','かれる','시들다; 생기나 기능이 쇠하다','植物が水分を失って死ぬ。また、勢いや機能が衰える。','水不足が続くと、若い苗まで枯れるおそれがある。','물 부족이 계속되면 어린 모종까지 시들 우려가 있다.'),
('n1-3394','2027-01-12','乾かす','かわかす','말리다; 수분을 없애다','水分を取り除いて乾いた状態にする。','洗浄した器具を十分に乾かす必要がある。','세척한 기구를 충분히 말릴 필요가 있다.'),
('n1-3395','2027-01-12','渇く','かわく','목마르다; 강하게 갈망하다','水分を欲する。また、何かを強く求める。','喉が渇く前に、少しずつ水分を補給した方がよい。','목이 마르기 전에 조금씩 수분을 보충하는 편이 좋다.'),
('n1-3396','2027-01-12','着せる','きせる','입히다; 책임이나 혐의를 덮어씌우다','人に衣服を着させる。また、責任や罪を負わせる。','一人だけに責任を着せる解決方法では、再発を防げない。','한 사람에게만 책임을 덮어씌우는 해결 방식으로는 재발을 막을 수 없다.'),
('n1-3397','2027-01-12','凍える','こごえる','얼어붙다; 추위로 몸이 몹시 차가워지다','厳しい寒さで体が冷え、動きにくくなる。','避難所の暖房が止まり、住民が凍える事態となった。','대피소 난방이 멈춰 주민들이 추위에 떠는 상황이 되었다.'),
('n1-3398','2027-01-12','焦がす','こがす','태우다; 애를 태우다','火や熱で焼いて黒くする。また、強く思い焦がれる。','火力が強すぎると鍋の底を焦がすので注意が必要だ。','불이 너무 세면 냄비 바닥을 태우므로 주의가 필요하다.'),
('n1-3399','2027-01-12','焦げる','こげる','타다; 열로 검게 변하다','火や熱によって焼けて黒くなる。','配線が焦げるような臭いがしたため、電源を切った。','배선이 타는 듯한 냄새가 나서 전원을 껐다.'),
('n1-3400','2027-01-12','裂く','さく','찢다; 관계나 집단을 갈라놓다','一つのものを強く引いて分ける。また、関係や集団を分裂させる。','対立をあおる発言は地域社会を裂くおそれがある。','대립을 부추기는 발언은 지역사회를 갈라놓을 우려가 있다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3401','2027-01-13','心得る','こころえる','알아두다; 이해하다; 맡아 처리하다','事情や方法を理解している。また、引き受けて処理する。','緊急時の手順を心得る担当者を各部署に配置した。','긴급 상황의 절차를 숙지한 담당자를 각 부서에 배치했다.'),
('n1-3402','2027-01-13','仕上がる','しあがる','완성되다; 마무리되다','作業が終わり、完成した状態になる。','報告書が仕上がるまで、数値の確認を続ける。','보고서가 완성될 때까지 수치를 계속 확인한다.'),
('n1-3403','2027-01-13','背負う','せおう','등에 지다; 책임이나 부담을 떠맡다','背中に載せて運ぶ。また、責任や負担を引き受ける。','一人で全ての責任を背負う必要はない。','혼자서 모든 책임을 짊어질 필요는 없다.'),
('n1-3404','2027-01-13','近付ける','ちかづける','가까이하다; 거리나 상태를 접근시키다','物や人の距離を近くする。また、目標の状態へ近づける。','制度を利用者の実情に近付けるため、運用を見直した。','제도를 이용자의 실정에 가깝게 만들기 위해 운영을 재검토했다.'),
('n1-3405','2027-01-13','近寄る','ちかよる','가까이 다가가다','人や物のそばへ近づく。','危険区域には決して近寄るべきではない。','위험 구역에는 절대로 가까이 가서는 안 된다.'),
('n1-3406','2027-01-13','出掛ける','でかける','외출하다; 어떤 목적지로 나가다','家などを出て、目的の場所へ行く。','遠方へ出掛ける前に、交通情報を確認した。','먼 곳으로 나가기 전에 교통 정보를 확인했다.'),
('n1-3407','2027-01-13','出迎える','でむかえる','마중 나가다; 나가서 맞이하다','到着する人を迎えるために、その場所へ出て待つ。','海外からの訪問団を空港で出迎える予定だ。','해외 방문단을 공항에서 맞이할 예정이다.'),
('n1-3408','2027-01-13','長引く','ながびく','오래 끌다; 예상보다 장기간 계속되다','予定や予想よりも長く続く。','交渉が長引くほど、双方の負担は大きくなる。','협상이 오래 끌수록 양측의 부담은 커진다.'),
('n1-3409','2027-01-13','流行る','はやる','유행하다; 질병 등이 널리 퍼지다','ある物事が広く人気になる。また、病気などが広がる。','短期間だけ流行る商品より、長く使える製品を目指す。','단기간만 유행하는 상품보다 오래 사용할 수 있는 제품을 지향한다.'),
('n1-3410','2027-01-13','真似る','まねる','흉내 내다; 본떠 따라 하다','他人の行動や方法を見て、同じように行う。','成功例をそのまま真似るだけでは、同じ成果は得られない。','성공 사례를 그대로 따라 하기만 해서는 같은 성과를 얻을 수 없다.'),
('n1-3411','2027-01-13','見送る','みおくる','배웅하다; 실행이나 결정을 보류하다','去る人を送り出す。また、実施や決定を今回は控える。','費用対効果が不明なため、導入を見送ることにした。','비용 대비 효과가 불분명해 도입을 보류하기로 했다.'),
('n1-3412','2027-01-13','見下ろす','みおろす','내려다보다; 높은 곳에서 아래를 보다','高い場所から下の方を見る。','展望台から市街地を見下ろすと、川の流れがよく分かる。','전망대에서 시가지를 내려다보면 강의 흐름이 잘 보인다.'),
('n1-3413','2027-01-13','見直す','みなおす','재검토하다; 다시 보고 평가를 바꾸다','もう一度調べて、内容や評価を改める。','事故の再発を防ぐため、作業手順を見直す必要がある。','사고 재발을 막기 위해 작업 절차를 재검토할 필요가 있다.'),
('n1-3414','2027-01-13','見慣れる','みなれる','눈에 익다; 자주 보아 익숙해지다','何度も見て、珍しく感じなくなる。','見慣れる表示でも、変更点がないか注意深く確認する。','눈에 익은 표시라도 변경된 점이 없는지 주의 깊게 확인한다.'),
('n1-3415','2027-01-13','見舞う','みまう','문병하다; 재해나 불행이 덮치다','病人などを訪ねて慰める。また、災害や不幸が人を襲う。','大規模な地震が地域を見舞う可能性に備える。','대규모 지진이 지역을 덮칠 가능성에 대비한다.'),
('n1-3416','2027-01-13','目指す','めざす','목표로 하다; 목적지를 향하다','目標の実現や目的地への到達を望んで進む。','誰もが利用しやすい公共サービスを目指す。','누구나 이용하기 쉬운 공공 서비스를 목표로 한다.'),
('n1-3417','2027-01-13','目立つ','めだつ','눈에 띄다; 두드러지다','周囲と比べて特に人の注意を引く。','最近は若年層の利用増加が目立つ。','최근에는 젊은 층의 이용 증가가 두드러진다.'),
('n1-3418','2027-01-13','物語る','ものがたる','이야기하다; 사실이나 상태를 분명히 보여주다','出来事を話す。また、事実や状況をはっきり示す。','この数値は地域格差の深刻さを物語る。','이 수치는 지역 격차의 심각성을 보여준다.'),
('n1-3419','2027-01-13','言い出す','いいだす','말을 꺼내다; 갑자기 주장하기 시작하다','新しい話題を口にする。また、主張を始める。','会議の終盤で新しい条件を言い出すのは望ましくない。','회의 막바지에 새로운 조건을 꺼내는 것은 바람직하지 않다.'),
('n1-3420','2027-01-13','受け持つ','うけもつ','담당하다; 책임지고 맡다','仕事や役割を責任を持って担当する。','今年は新人研修を受け持つことになった。','올해는 신입사원 연수를 담당하게 되었다.'),
('n1-3421','2027-01-14','打ち消す','うちけす','부정하다; 효과나 영향을 상쇄하다','発言を否定する。また、効果や影響をなくす。','一部の成功だけで全体の問題を打ち消すことはできない。','일부 성공만으로 전체의 문제를 상쇄할 수는 없다.'),
('n1-3422','2027-01-14','売り切れる','うりきれる','매진되다; 전부 팔리다','商品が全部売れて、在庫がなくなる。','限定商品は発売直後に売り切れる可能性が高い。','한정 상품은 발매 직후 매진될 가능성이 높다.'),
('n1-3423','2027-01-14','追い掛ける','おいかける','뒤쫓다; 목표나 유행을 계속 좇다','先に進む人や物の後を追う。また、目標などを求め続ける。','目先の利益だけを追い掛ける経営には限界がある。','눈앞의 이익만 좇는 경영에는 한계가 있다.'),
('n1-3424','2027-01-14','追い越す','おいこす','추월하다; 앞선 대상보다 더 앞서다','前を進む人や物に追いつき、その先へ出る。','新興企業が短期間で既存企業を追い越す例もある。','신생 기업이 단기간에 기존 기업을 추월하는 사례도 있다.'),
('n1-3425','2027-01-14','思い込む','おもいこむ','굳게 믿다; 근거 없이 단정하다','ある考えを正しいと強く信じ、他の可能性を考えなくなる。','経験があるから必ず成功すると思い込むのは危険だ。','경험이 있으니 반드시 성공한다고 단정하는 것은 위험하다.'),
('n1-3426','2027-01-14','思い付く','おもいつく','생각해 내다; 문득 떠오르다','考えや方法がふと心に浮かぶ。','思い付く案を並べるだけでなく、実現可能性も検討する。','떠오르는 안을 나열하기만 하지 말고 실현 가능성도 검토한다.'),
('n1-3427','2027-01-14','組み立てる','くみたてる','조립하다; 논리나 계획을 체계적으로 구성하다','部品を組み合わせて形を作る。また、論理や計画を構成する。','複数の証拠を基に論理を組み立てる。','여러 증거를 바탕으로 논리를 구성한다.'),
('n1-3428','2027-01-14','締め切る','しめきる','마감하다; 신청이나 접수를 끝내다','応募や受付などを決められた時点で終える。','定員に達した場合は期限前でも募集を締め切る。','정원에 도달하면 기한 전이라도 모집을 마감한다.'),
('n1-3429','2027-01-14','透き通る','すきとおる','투명하게 비치다; 맑고 선명하다','向こう側が見えるほど透明である。また、音や声が澄んでいる。','湖の水は底が見えるほど透き通る。','호수의 물은 바닥이 보일 정도로 맑고 투명하다.'),
('n1-3430','2027-01-14','立ち止まる','たちどまる','멈춰 서다; 진행을 잠시 멈추고 생각하다','歩くのをやめてその場に止まる。また、進行を止めて考える。','判断に迷ったときは、一度立ち止まることも必要だ。','판단이 어려울 때는 한 번 멈춰 생각하는 것도 필요하다.'),
('n1-3431','2027-01-14','突っ込む','つっこむ','밀어 넣다; 깊이 파고들다; 날카롭게 지적하다','勢いよく中へ入れる。また、深く追及したり鋭く指摘したりする。','曖昧な説明には、さらに突っ込む質問が必要だ。','모호한 설명에는 더 깊이 파고드는 질문이 필요하다.'),
('n1-3432','2027-01-14','釣り合う','つりあう','균형이 맞다; 서로 어울리다','二つのものの程度や価値が均衡している。','負担と得られる効果が釣り合うか慎重に判断する。','부담과 얻을 수 있는 효과가 균형을 이루는지 신중히 판단한다.'),
('n1-3433','2027-01-14','溶け込む','とけこむ','녹아들다; 집단이나 환경에 자연스럽게 섞이다','液体などの中に混ざる。また、集団や環境になじむ。','新しい職場に溶け込むには、周囲との対話が欠かせない。','새 직장에 적응하려면 주변 사람들과의 대화가 필수적이다.'),
('n1-3434','2027-01-14','飛び込む','とびこむ','뛰어들다; 갑자기 안으로 들어가다','勢いよく中へ入る。また、新しい分野などへ思い切って入る。','十分な準備もなく未知の市場へ飛び込むのは危険だ。','충분한 준비 없이 미지의 시장에 뛰어드는 것은 위험하다.'),
('n1-3435','2027-01-14','取り入れる','とりいれる','받아들이다; 도입하다; 안으로 들이다','外にあるものや考え方を受け入れて活用する。','利用者の意見を設計に取り入れる仕組みを整えた。','이용자의 의견을 설계에 반영하는 체계를 마련했다.'),
('n1-3436','2027-01-14','取り消す','とりけす','취소하다; 이전 결정이나 발언의 효력을 없애다','一度決めたことや述べたことを無効にする。','虚偽の申告が判明した場合、許可を取り消すことがある。','허위 신고가 밝혀지면 허가를 취소할 수 있다.'),
('n1-3437','2027-01-14','取り出す','とりだす','꺼내다; 여러 것 중에서 골라 내다','中にあるものを外へ出す。また、必要なものを選び出す。','大量の記録から必要な情報だけを取り出す。','방대한 기록에서 필요한 정보만 추출한다.'),
('n1-3438','2027-01-14','話し掛ける','はなしかける','말을 걸다','相手に向かって話を始める。','困っている旅行者を見かけ、職員が日本語で話し掛ける。','곤란해하는 여행객을 보고 직원이 일본어로 말을 건다.'),
('n1-3439','2027-01-14','払い戻す','はらいもどす','환불하다; 지불한 돈을 돌려주다','一度受け取った代金や料金を返す。','公演が中止になった場合、チケット代を払い戻す。','공연이 취소되면 티켓 요금을 환불한다.'),
('n1-3440','2027-01-14','引き止める','ひきとめる','붙잡아 두다; 떠나거나 그만두지 못하게 말리다','立ち去ろうとする人を止め、その場に残らせる。','本人の意思を無視して退職を引き止めるべきではない。','본인의 의사를 무시하고 퇴직을 만류해서는 안 된다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3441','2027-01-15','出来上がる','できあがる','완성되다; 다 만들어지다','作業や製作が終わり、完成した状態になる。','最終版が出来上がるまで、内容の確認を続ける。','최종본이 완성될 때까지 내용을 계속 확인한다.'),
('n1-3442','2027-01-15','ひっくり返す','ひっくりかえす','뒤집다; 전복시키다; 결과를 뒤바꾸다','上下や表裏を逆にする。また、状況や結論を逆転させる。','新しい証拠が従来の結論をひっくり返す可能性がある。','새로운 증거가 기존 결론을 뒤집을 가능성이 있다.'),
('n1-3443','2027-01-15','ひっくり返る','ひっくりかえる','뒤집히다; 전복되다; 상황이 역전되다','上下や表裏が逆になる。また、状況が大きく逆転する。','一つの判定で試合の流れがひっくり返ることもある。','하나의 판정으로 경기 흐름이 뒤집히기도 한다.'),
('n1-3444','2027-01-15','威張る','いばる','뽐내다; 거드름 피우다','自分を偉いと思わせるような態度を取る。','役職が上だからといって威張る人は信頼されない。','직급이 높다고 거드름을 피우는 사람은 신뢰받지 못한다.'),
('n1-3445','2027-01-15','裏返す','うらがえす','뒤집다; 안팎을 바꾸다','表と裏を反対にする。','資料を裏返すと、裏面に注意事項が記載されている。','자료를 뒤집으면 뒷면에 주의 사항이 적혀 있다.'),
('n1-3446','2027-01-15','落ち着く','おちつく','진정되다; 안정되다; 정착하다','気持ちや状況が静まり、安定した状態になる。','市場が落ち着くまでは慎重な判断が求められる。','시장이 안정될 때까지 신중한 판단이 필요하다.'),
('n1-3447','2027-01-15','片付く','かたづく','정리되다; 해결되다','物が整理される。また、問題や仕事が処理される。','この案件が片付くまで、新しい仕事には着手できない。','이 안건이 해결될 때까지 새 업무에는 착수할 수 없다.'),
('n1-3448','2027-01-15','例える','たとえる','비유하다; 예를 들어 설명하다','ある物事を、似た別のものに置き換えて説明する。','複雑な仕組みを身近な道具に例えると理解しやすい。','복잡한 구조를 친숙한 도구에 비유하면 이해하기 쉽다.'),
('n1-3449','2027-01-15','区切る','くぎる','구분하다; 단락 짓다; 일단락하다','連続するものを一定のところで分ける。','長い説明を項目ごとに区切ると理解しやすい。','긴 설명을 항목별로 구분하면 이해하기 쉽다.'),
('n1-3450','2027-01-15','腰掛ける','こしかける','걸터앉다; 앉다','椅子や台などに腰を下ろす。','受付の順番が来るまで、こちらに腰掛けるよう案内された。','접수 순서가 올 때까지 이곳에 앉아 있으라는 안내를 받았다.'),
('n1-3451','2027-01-15','言付ける','ことづける','전언을 부탁하다; 물건을 맡겨 전하게 하다','人を介して伝言や品物を相手に届けてもらう。','不在の担当者に折り返し連絡するよう言付ける。','부재중인 담당자에게 다시 연락해 달라고 전언을 부탁한다.'),
('n1-3452','2027-01-15','千切る','ちぎる','잘게 뜯다; 떼어 내다','手で細かく切ったり、一部を引き離したりする。','古い書類を不用意に千切る前に、保存期限を確認する。','오래된 서류를 함부로 찢기 전에 보존 기한을 확인한다.'),
('n1-3453','2027-01-15','付き合う','つきあう','교제하다; 상대해 주다; 함께하다','人と交際する。また、相手の行動に合わせて一緒に行う。','異なる価値観を持つ人とも丁寧に付き合う姿勢が必要だ。','다른 가치관을 가진 사람과도 성실하게 교류하는 자세가 필요하다.'),
('n1-3454','2027-01-15','引き受ける','ひきうける','맡다; 인수하다; 책임지다','仕事や責任を自分が受け持つ。','条件を確認せずに大きな案件を引き受けるのは危険だ。','조건을 확인하지 않고 큰 안건을 맡는 것은 위험하다.'),
('n1-3455','2027-01-15','引き返す','ひきかえす','되돌아가다; 되돌리다','進んできた道を逆に戻る。','天候が悪化したため、途中で引き返すことにした。','날씨가 악화되어 도중에 되돌아가기로 했다.'),
('n1-3456','2027-01-15','引き出す','ひきだす','꺼내다; 인출하다; 능력이나 의견을 끌어내다','中から外へ出す。また、能力や意見をうまく表に出させる。','対話を通じて相手の本音を引き出す。','대화를 통해 상대의 속마음을 끌어낸다.'),
('n1-3457','2027-01-15','振る舞う','ふるまう','행동하다; 대접하다','ある態度で行動する。また、飲食物を人に提供する。','公の場では立場にふさわしく振る舞う必要がある。','공적인 자리에서는 지위에 걸맞게 행동할 필요가 있다.'),
('n1-3458','2027-01-15','見つかる','みつかる','발견되다; 들키다','探していたものが発見される。また、隠していたことが知られる。','調査によって新たな問題が見つかる可能性がある。','조사를 통해 새로운 문제가 발견될 가능성이 있다.'),
('n1-3459','2027-01-15','見つける','みつける','찾아내다; 발견하다','探していたものや新しい事実を発見する。','大量の記録から異常な傾向を見つける。','대량의 기록에서 이상한 경향을 찾아낸다.'),
('n1-3460','2027-01-15','言いつける','いいつける','명령하다; 일러바치다','人に命令する。また、他人の行動を告げ口する。','理由も説明せず部下に作業を言いつけるべきではない。','이유도 설명하지 않고 부하에게 작업을 명령해서는 안 된다.'),
('n1-3461','2027-01-16','気を付ける','きをつける','조심하다; 주의하다','失敗や危険がないよう注意する。','個人情報を扱う際は誤送信に気を付ける。','개인 정보를 다룰 때는 오발송에 주의한다.'),
('n1-3462','2027-01-16','突き当たる','つきあたる','맞부딪치다; 막다른 곳에 이르다; 난관에 봉착하다','物や行き止まりにぶつかる。また、困難な問題に直面する。','計画を進めるうちに予想外の壁に突き当たる。','계획을 진행하다가 예상 밖의 장벽에 부딪힌다.'),
('n1-3463','2027-01-16','通り掛かる','とおりかかる','마침 지나가다; 지나가던 길이다','ある場所を偶然、または途中で通る。','現場を通り掛かると、多くの人が集まっていた。','현장을 지나가다가 많은 사람이 모여 있는 것을 보았다.'),
('n1-3464','2027-01-16','払い込む','はらいこむ','납입하다; 송금하다','金銭を金融機関や指定先へ納める。','保険料を指定された口座へ払い込む。','보험료를 지정된 계좌로 납입한다.'),
('n1-3465','2027-01-16','張り切る','はりきる','의욕이 넘치다; 힘을 내다','意欲に満ちて、元気よく物事に取り組む。','初日から張り切るのはよいが、無理は禁物だ。','첫날부터 의욕을 내는 것은 좋지만 무리는 금물이다.'),
('n1-3466','2027-01-16','引っ掛かる','ひっかかる','걸리다; 속다; 마음에 걸리다','物に掛かって止まる。また、だまされたり疑問を感じたりする。','説明の一部がどうしても引っ掛かるので、再確認した。','설명의 일부가 아무래도 마음에 걸려 다시 확인했다.'),
('n1-3467','2027-01-16','引っ込む','ひっこむ','들어가다; 물러나다; 움푹 들어가다','表から奥へ入る。また、人前や役割から退く。','反対意見が出たからといって、すぐに引っ込む必要はない。','반대 의견이 나왔다고 해서 바로 물러날 필요는 없다.'),
('n1-3468','2027-01-16','待ち合わせる','まちあわせる','약속하여 만나다; 만나기로 하다','時刻と場所を決め、互いに待って会う。','駅の改札前で同僚と待ち合わせる。','역 개찰구 앞에서 동료와 만나기로 한다.'),
('n1-3469','2027-01-16','呼び掛ける','よびかける','부르다; 호소하다; 참여를 촉구하다','声を掛ける。また、多くの人に行動や協力を求める。','自治体は住民に節電への協力を呼び掛ける。','지자체는 주민에게 절전에 협조해 달라고 호소한다.'),
('n1-3470','2027-01-16','呼び出す','よびだす','불러내다; 호출하다','人を指定の場所へ来させる。また、機能や情報を画面に出す。','必要に応じて担当者を会議室へ呼び出す。','필요에 따라 담당자를 회의실로 호출한다.'),
('n1-3471','2027-01-16','遭う','あう','(재난·사고 등을) 당하다; 맞닥뜨리다','災難や事故など、好ましくない出来事を経験する。','旅先で盗難に遭う可能性も考えて備える。','여행지에서 도난을 당할 가능성도 생각해 대비한다.'),
('n1-3472','2027-01-16','扇ぐ','あおぐ','부채질하다; 바람을 일으키다','うちわなどを動かして風を起こす。','煙がこちらへ来ないよう、反対方向へ扇ぐ。','연기가 이쪽으로 오지 않도록 반대 방향으로 부채질한다.'),
('n1-3473','2027-01-16','挙げる','あげる','들다; 제시하다; 성과를 올리다','高く上げる。また、例や理由を示したり、成果を生み出したりする。','具体例を三つ挙げると、主張が伝わりやすい。','구체적인 예를 세 가지 들면 주장이 전달되기 쉽다.'),
('n1-3474','2027-01-16','憧れる','あこがれる','동경하다; 선망하다','理想とする人や物事に強く心を引かれる。','海外で働く生活に憧れる若者は少なくない。','해외에서 일하는 생활을 동경하는 젊은이는 적지 않다.'),
('n1-3475','2027-01-16','暖まる','あたたまる','따뜻해지다; 몸이 데워지다','温度が上がり、暖かい状態になる。','部屋が暖まるまで、上着を着たまま待った。','방이 따뜻해질 때까지 겉옷을 입은 채 기다렸다.'),
('n1-3476','2027-01-16','暖める','あたためる','따뜻하게 하다; 데우다; 구상을 다듬다','温度を上げる。また、考えや計画を内密に育てる。','長年暖める企画を、来年度に実行へ移す。','오랫동안 다듬어 온 기획을 내년에 실행에 옮긴다.'),
('n1-3477','2027-01-16','応じる','おうじる','응하다; 대응하다; ~에 따라 달라지다','求めに答える。また、状況や条件に合わせる。','利用者の要望に応じる形でサービスを改善した。','이용자의 요구에 부응하는 형태로 서비스를 개선했다.'),
('n1-3478','2027-01-16','押さえる','おさえる','누르다; 억누르다; 요점을 파악하다; 확보하다','上から力を加える。また、重要点を理解したり必要なものを確保したりする。','議論に入る前に、基本的な論点を押さえる。','논의에 들어가기 전에 기본 쟁점을 파악한다.'),
('n1-3479','2027-01-16','教わる','おそわる','배우다; 가르침을 받다','人から知識や方法を教えてもらう。','専門家から安全な操作方法を教わる。','전문가에게 안전한 조작 방법을 배운다.'),
('n1-3480','2027-01-16','関わる','かかわる','관계되다; 관여하다; 영향을 미치다','物事と関係を持つ。また、重大な影響を及ぼす。','人命に関わる判断には十分な検証が必要だ。','인명과 관련된 판단에는 충분한 검증이 필요하다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3481','2027-01-17','揚げる','あげる','튀기다; 높이 올리다','油で調理する。また、旗などを高く上げる。','注文を受けてから魚を揚げるので、少し時間がかかる。','주문을 받은 뒤 생선을 튀기기 때문에 시간이 조금 걸린다.'),
('n1-3482','2027-01-17','次ぐ','つぐ','뒤를 잇다; 다음가다','あるもののすぐ後に続く。また、程度や順位がその次である。','この地域は首都圏に次ぐ規模の市場を持つ。','이 지역은 수도권 다음가는 규모의 시장을 갖고 있다.'),
('n1-3483','2027-01-17','配る','くばる','나누어 주다; 배부하다; 신경을 쓰다','複数の人に分けて渡す。また、周囲に注意を向ける。','会議の開始前に参加者へ資料を配る。','회의 시작 전에 참가자에게 자료를 나누어 준다.'),
('n1-3484','2027-01-17','汲む','くむ','물을 긷다; 사정을 헤아리다','水などをすくい取る。また、事情や気持ちを理解して考慮する。','現場の事情を汲む柔軟な対応が求められる。','현장의 사정을 헤아린 유연한 대응이 요구된다.'),
('n1-3485','2027-01-17','蹴る','ける','차다; 제안 등을 거절하다','足で強く打つ。また、提案や要求を拒絶する。','会社側が組合の要求を一方的に蹴ることは避けるべきだ。','회사 측이 노조의 요구를 일방적으로 거절하는 것은 피해야 한다.'),
('n1-3486','2027-01-17','越す','こす','넘다; 건너다; 이사하다','境界や基準を越える。また、別の場所へ移り住む。','予算が百万円を越す場合は追加の承認が必要だ。','예산이 백만 엔을 넘는 경우 추가 승인이 필요하다.'),
('n1-3487','2027-01-17','擦る','こする','문지르다; 비비다','物の表面に別の物を押し当てて繰り返し動かす。','汚れを落とそうとして強く擦ると、表面が傷つく。','얼룩을 지우려고 세게 문지르면 표면에 흠집이 생긴다.'),
('n1-3488','2027-01-17','零れる','こぼれる','쏟아지다; 넘쳐흐르다; 무심코 새어 나오다','容器から外へ漏れ落ちる。また、感情や言葉が自然に表へ出る。','説明を聞いた参加者から安堵の笑みが零れる。','설명을 들은 참가자들에게서 안도의 미소가 흘러나온다.'),
('n1-3489','2027-01-17','転がす','ころがす','굴리다; 넘어뜨리다','物を回転させながら移動させる。','重い荷物は台車に載せて転がすほうが安全だ。','무거운 짐은 운반대에 올려 굴리는 편이 안전하다.'),
('n1-3490','2027-01-17','転がる','ころがる','구르다; 나뒹굴다','物が回転しながら移動する。また、倒れて横になる。','固定しないと容器が床を転がる恐れがある。','고정하지 않으면 용기가 바닥을 굴러갈 우려가 있다.'),
('n1-3491','2027-01-17','捜す','さがす','수색하다; 잃어버린 것을 찾다','見失った人や物の所在を調べ求める。','警察は目撃情報を基に行方不明者を捜す。','경찰은 목격 정보를 바탕으로 실종자를 수색한다.'),
('n1-3492','2027-01-17','刺さる','ささる','박히다; 찔리다; 마음에 강하게 와닿다','先の鋭い物が中に入り込む。また、言葉などが強く心に残る。','率直な指摘が胸に刺さることもある。','솔직한 지적이 가슴에 아프게 와닿기도 한다.'),
('n1-3493','2027-01-17','刺す','さす','찌르다; 쏘다','先の鋭い物を突き入れる。また、虫が針などで攻撃する。','蜂が人を刺す恐れがあるため、巣に近づかないでください。','벌이 사람을 쏠 우려가 있으므로 벌집에 접근하지 마세요.'),
('n1-3494','2027-01-17','挿す','さす','꽂다; 끼워 넣다','細長い物を中へ入れたり、花などを器に入れたりする。','受付の花瓶に季節の花を挿す。','접수대의 꽃병에 계절 꽃을 꽂는다.'),
('n1-3495','2027-01-17','射す','さす','빛이 비치다','光が一定の方向から入り込む。','窓から朝日が射すと、部屋全体が明るくなった。','창문으로 아침 햇살이 비치자 방 전체가 밝아졌다.'),
('n1-3496','2027-01-17','錆びる','さびる','녹슬다; 기능이나 감각이 둔해지다','金属にさびが生じる。また、能力や感覚が衰える。','雨ざらしにすると金属部品が錆びる。','비에 그대로 노출하면 금속 부품이 녹슨다.'),
('n1-3497','2027-01-17','冷ます','さます','식히다; 열기나 흥분을 가라앉히다','熱いものの温度を下げる。また、興奮を落ち着かせる。','加熱した試料を十分に冷ますまで触れてはいけない。','가열한 시료를 충분히 식힐 때까지 만져서는 안 된다.'),
('n1-3498','2027-01-17','冷める','さめる','식다; 열정이나 흥미가 사라지다','温度が下がる。また、熱意や興味が薄れる。','期待が大きすぎると、失望したときに熱意が冷める。','기대가 지나치게 크면 실망했을 때 열의가 식는다.'),
('n1-3499','2027-01-17','敷く','しく','깔다; 제도나 체제를 마련하다','平らに広げて置く。また、制度や体制を設ける。','災害時に迅速に対応できる体制を敷く。','재난 시 신속히 대응할 수 있는 체제를 마련한다.'),
('n1-3500','2027-01-17','茂る','しげる','무성하다; 우거지다','草木の枝葉が盛んに生い育つ。','夏になると庭の草木が一斉に茂る。','여름이 되면 정원의 초목이 일제히 무성해진다.'),
('n1-3501','2027-01-18','静まる','しずまる','조용해지다; 진정되다; 가라앉다','騒ぎや勢いが弱まり、静かな状態になる。','会場が静まるのを待って、司会者が説明を始めた。','행사장이 조용해지기를 기다린 뒤 사회자가 설명을 시작했다.'),
('n1-3502','2027-01-18','湿る','しめる','축축해지다; 습기를 띠다','水分を含んで、少しぬれた状態になる。','保管場所の湿度が高いと紙が湿る。','보관 장소의 습도가 높으면 종이가 눅눅해진다.'),
('n1-3503','2027-01-18','澄む','すむ','맑아지다; 투명해지다; 소리가 청명하다','濁りがなく透明になる。また、音や空気が清らかになる。','冬の朝は空気が澄むため、遠くの山まで見える。','겨울 아침에는 공기가 맑아 먼 산까지 보인다.'),
('n1-3504','2027-01-18','刷る','する','인쇄하다; 찍어 내다','文字や絵を紙などに印刷する。','修正内容を確認してから資料を刷る。','수정 내용을 확인한 뒤 자료를 인쇄한다.'),
('n1-3505','2027-01-18','剃る','そる','(털을) 깎다; 면도하다','刃物で髪やひげなどを根元から切り取る。','肌を傷つけないよう、慎重にひげを剃る。','피부를 다치지 않도록 조심스럽게 수염을 깎는다.'),
('n1-3506','2027-01-18','炊く','たく','밥을 짓다','米などを水とともに加熱して食べられる状態にする。','災害訓練では屋外で大量の米を炊く。','재난 훈련에서는 야외에서 많은 양의 밥을 짓는다.'),
('n1-3507','2027-01-18','焚く','たく','불을 피우다; 연료를 태우다','燃料を燃やして火を起こす。','乾燥した場所で火を焚く際は十分な注意が必要だ。','건조한 장소에서 불을 피울 때는 충분한 주의가 필요하다.'),
('n1-3508','2027-01-18','助かる','たすかる','살아나다; 도움을 받다; 수고를 덜다','危険や困難から逃れる。また、援助によって負担が軽くなる。','資料を事前に共有してもらえると非常に助かる。','자료를 미리 공유해 주면 매우 도움이 된다.'),
('n1-3509','2027-01-18','畳む','たたむ','개다; 접다; 사업을 정리하다','広げたものを折り重ねる。また、店や事業を終える。','長年続けた店を畳む決断は容易ではない。','오랫동안 운영한 가게를 정리하는 결정은 쉽지 않다.'),
('n1-3510','2027-01-18','建つ','たつ','세워지다; 건물이 들어서다','建物などが造られ、その場所に存在する。','駅前に新しい公共施設が建つ予定だ。','역 앞에 새로운 공공시설이 들어설 예정이다.'),
('n1-3511','2027-01-18','発つ','たつ','출발하다; 떠나다','目的地に向かって、その場所を出発する。','調査団は早朝に現地へ発つ。','조사단은 이른 아침 현지로 출발한다.'),
('n1-3512','2027-01-18','溜まる','たまる','쌓이다; 모이다; 밀리다','物や仕事などが少しずつ増えて一か所に集まる。','処理を先延ばしにすると未対応の案件が溜まる。','처리를 미루면 미대응 안건이 쌓인다.'),
('n1-3513','2027-01-18','溜める','ためる','모으다; 저축하다; 쌓아 두다','物や金銭などを少しずつ集めて蓄える。','問題を一人で溜める前に周囲へ相談したほうがよい。','문제를 혼자 쌓아 두기 전에 주변에 상담하는 편이 좋다.'),
('n1-3514','2027-01-18','足る','たる','충분하다; 족하다','必要な量や条件を満たしている。','この証拠だけでは事実を断定するに足るとは言えない。','이 증거만으로는 사실을 단정하기에 충분하다고 할 수 없다.'),
('n1-3515','2027-01-18','縮れる','ちぢれる','곱슬거리다; 오그라들다','しわが寄ったり、細かく曲がった状態になったりする。','高温にさらすと素材の表面が縮れることがある。','고온에 노출하면 소재 표면이 오그라들 수 있다.'),
('n1-3516','2027-01-18','散らかす','ちらかす','어질러 놓다; 흩뜨리다','物を乱雑に広げ、整理されていない状態にする。','共有スペースに私物を散らかすのはやめてください。','공용 공간에 개인 물건을 어질러 놓지 마세요.'),
('n1-3517','2027-01-18','散らかる','ちらかる','어질러지다; 흐트러져 있다','物が乱雑に広がり、整理されていない状態になる。','資料を分類しないと机の上がすぐ散らかる。','자료를 분류하지 않으면 책상 위가 금세 어질러진다.'),
('n1-3518','2027-01-18','散らす','ちらす','흩뜨리다; 분산시키다','一か所に集まっているものを広くばらばらにする。','観客を安全な場所へ散らすため、複数の出口を開放した。','관객을 안전한 곳으로 분산시키기 위해 여러 출구를 개방했다.'),
('n1-3519','2027-01-18','散る','ちる','흩어지다; 꽃이 지다','まとまっていたものが離れて広がる。また、花が枝から落ちる。','強い風が吹くと、満開の桜もすぐに散る。','강한 바람이 불면 만개한 벚꽃도 금세 진다.'),
('n1-3520','2027-01-18','点く','つく','불이 켜지다; 점화되다','照明や火がついて明るくなる。','人が近づくと自動的に照明が点く。','사람이 가까이 가면 자동으로 조명이 켜진다.');
INSERT INTO _n1_b8_words_0123(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-3521','2027-01-19','分類','ぶんるい','분류; 공통된 성질에 따라 종류를 나눔','共通する性質や基準に従って、物事を種類ごとに分けること。','収集した意見を論点ごとに分類してから分析した。','수집한 의견을 논점별로 분류한 뒤 분석했다.'),
('n1-3522','2027-01-19','並行','へいこう','병행; 둘 이상의 일을 동시에 나란히 진행함','二つ以上の物事が、同時に並んで進むこと。','制度の見直しと現場への聞き取りを並行して進める。','제도 재검토와 현장 의견 청취를 병행해 진행한다.'),
('n1-3523','2027-01-19','編集','へんしゅう','편집; 자료를 모아 구성하고 다듬음','資料や文章などを集め、選択・配列して一つにまとめること。','複数の執筆者による原稿を一冊の報告書に編集した。','여러 집필자의 원고를 한 권의 보고서로 편집했다.'),
('n1-3524','2027-01-19','防止','ぼうし','방지; 좋지 않은 일이 생기지 않도록 막음','好ましくない事態が起こらないように防ぐこと。','事故の再発防止には原因の共有と手順の改善が欠かせない。','사고 재발 방지에는 원인 공유와 절차 개선이 필수적이다.'),
('n1-3525','2027-01-19','方針','ほうしん','방침; 일을 처리하거나 나아갈 기본 방향','物事を進める際の基本的な方向や考え方。','調査結果を踏まえて、組織の運営方針を改めた。','조사 결과를 바탕으로 조직의 운영 방침을 바꾸었다.'),
('n1-3526','2027-01-19','法則','ほうそく','법칙; 일정한 조건에서 성립하는 규칙적인 관계','一定の条件の下で成り立つ、物事の規則的な関係。','限られた事例だけで普遍的な法則を導くのは危険だ。','한정된 사례만으로 보편적인 법칙을 도출하는 것은 위험하다.'),
('n1-3527','2027-01-19','膨大','ぼうだい','방대함; 규모나 수량이 매우 큼','数量や規模が非常に大きいさま。','膨大な記録から必要な情報だけを抽出する仕組みを整えた。','방대한 기록에서 필요한 정보만 추출하는 체계를 마련했다.'),
('n1-3528','2027-01-19','防犯','ぼうはん','방범; 범죄를 미리 막음','犯罪が起こらないように予防すること。','地域の防犯を強化するため、夜間の巡回を増やした。','지역 방범을 강화하기 위해 야간 순찰을 늘렸다.'),
('n1-3529','2027-01-19','募集','ぼしゅう','모집; 널리 알려 사람이나 작품 등을 모음','広く呼びかけて、人員・作品・意見などを集めること。','市は新しい計画に対する住民の意見を募集している。','시는 새로운 계획에 대한 주민 의견을 모집하고 있다.'),
('n1-3530','2027-01-19','本来','ほんらい','본래; 원래부터 그러함; 마땅히 그래야 함','もともとの性質や状態。また、当然そうあるべきこと。','この制度は本来、支援を受けにくい人を守るために設けられた。','이 제도는 본래 지원받기 어려운 사람을 보호하기 위해 마련되었다.'),
('n1-3531','2027-01-19','摩擦','まさつ','마찰; 맞닿은 물체의 운동을 방해하는 힘; 사람 사이의 충돌','接触する物体の運動を妨げる力。また、人や集団の間の対立。','役割を曖昧にしたままでは、部署間の摩擦が生じやすい。','역할을 모호하게 둔 채로는 부서 간 마찰이 생기기 쉽다.'),
('n1-3532','2027-01-19','身分','みぶん','신분; 사회나 법률상 차지하는 지위','社会や法律の上で個人が占める地位や立場。','契約の前に本人確認書類で身分を確認する。','계약 전에 본인 확인 서류로 신분을 확인한다.'),
('n1-3533','2027-01-19','未満','みまん','미만; 정해진 수나 정도에 이르지 않음','ある数値や程度に達していないこと。','利用者が十八歳未満の場合は保護者の同意が必要だ。','이용자가 18세 미만인 경우 보호자의 동의가 필요하다.'),
('n1-3534','2027-01-19','民間','みんかん','민간; 정부 기관이 아닌 일반 사회나 사기업 영역','政府や公的機関に属さない、一般の社会や企業の領域。','公共部門と民間が連携して地域交通を維持している。','공공 부문과 민간이 연계해 지역 교통을 유지하고 있다.'),
('n1-3535','2027-01-19','無限','むげん','무한; 한계가 없음','数量や範囲に限りがないこと。','資源は無限ではないという前提で政策を設計すべきだ。','자원은 무한하지 않다는 전제로 정책을 설계해야 한다.'),
('n1-3536','2027-01-19','無数','むすう','무수; 셀 수 없을 만큼 수가 많음','数え切れないほど数が多いこと。','一つの決定の背後には無数の小さな判断が積み重なっている。','하나의 결정 뒤에는 무수한 작은 판단이 쌓여 있다.'),
('n1-3537','2027-01-19','迷信','めいしん','미신; 합리적 근거 없이 믿는 생각','合理的な根拠がないまま信じられている考え。','科学的な説明が広まっても、古い迷信が残ることがある。','과학적 설명이 퍼져도 오래된 미신이 남는 경우가 있다.'),
('n1-3538','2027-01-19','目安','めやす','기준; 판단이나 행동의 대략적인 기준','判断や行動を決める際のおおよその基準。','所要時間は三十分を目安としているが、状況により変わる。','소요 시간은 30분을 기준으로 하지만 상황에 따라 달라진다.'),
('n1-3539','2027-01-19','問答','もんどう','문답; 질문하고 대답함; 서로 논쟁함','問いと答えを交わすこと。また、議論をやり取りすること。','短い問答を重ねるうちに、双方の認識の違いが明らかになった。','짧은 문답을 거듭하는 동안 양측의 인식 차이가 분명해졌다.'),
('n1-3540','2027-01-19','友好','ゆうこう','우호; 서로 친하고 좋은 관계를 유지함','互いに親しく、良い関係を保つこと。','両都市は文化交流を通じて友好関係を築いてきた。','두 도시는 문화 교류를 통해 우호 관계를 쌓아 왔다.'),
('n1-3541','2027-01-20','輸送','ゆそう','수송; 사람이나 물자를 다른 장소로 운반함','人や物資を別の場所へ運ぶこと。','災害地域へ支援物資を輸送する経路を確保した。','재해 지역으로 지원 물자를 수송할 경로를 확보했다.'),
('n1-3542','2027-01-20','油断','ゆだん','방심; 주의를 게을리함','注意を怠り、警戒を緩めること。','小さな異常だからと油断すると、重大な事故につながりかねない。','작은 이상이라고 방심하면 중대한 사고로 이어질 수 있다.'),
('n1-3543','2027-01-20','用語','ようご','용어; 특정 분야에서 정해진 의미로 쓰는 말','特定の分野で、一定の意味を持って使われる言葉。','専門用語には初出時に簡潔な説明を添えた。','전문 용어에는 처음 나올 때 간단한 설명을 덧붙였다.'),
('n1-3544','2027-01-20','要旨','ようし','요지; 내용의 중심이 되는 중요한 뜻','文章や発言の中心となる重要な内容。','報告書の要旨を冒頭にまとめ、結論を分かりやすくした。','보고서 요지를 서두에 정리해 결론을 알기 쉽게 했다.'),
('n1-3545','2027-01-20','用途','ようと','용도; 물건이나 자금을 사용하는 목적','物や資金などを使用する目的。','補助金の用途は規則によって厳しく限定されている。','보조금의 용도는 규칙에 따라 엄격히 제한되어 있다.'),
('n1-3546','2027-01-20','要領','ようりょう','요령; 일의 핵심이나 처리 방법; 핵심 내용','物事の要点や、うまく処理するための方法。','申請要領を確認し、必要な書類を期限内に提出した。','신청 요령을 확인하고 필요한 서류를 기한 안에 제출했다.'),
('n1-3547','2027-01-20','予備','よび','예비; 필요할 때를 대비해 미리 준비함','必要な場合に備えて、あらかじめ用意しておくこと。','停電に備えて予備の電源と通信手段を確保している。','정전에 대비해 예비 전원과 통신 수단을 확보하고 있다.'),
('n1-3548','2027-01-20','流域','りゅういき','유역; 한 강으로 물이 모이는 지역','降った水が一つの川に集まる地域。','洪水対策は自治体の境界ではなく流域全体で考える必要がある。','홍수 대책은 지자체 경계가 아니라 유역 전체로 생각할 필요가 있다.'),
('n1-3549','2027-01-20','臨時','りんじ','임시; 정해진 때가 아닌 필요에 따라 일시적으로 마련함','必要に応じて、一時的または予定外に設けること。','利用者の増加に対応するため、臨時の窓口を設置した。','이용자 증가에 대응하기 위해 임시 창구를 설치했다.'),
('n1-3550','2027-01-20','例外','れいがい','예외; 일반 원칙이나 규칙에 들어맞지 않는 것','一般的な原則や規則に当てはまらないもの。','原則を示すだけでなく、どの条件を例外とするかも明記した。','원칙만 제시하지 않고 어떤 조건을 예외로 할지도 명시했다.'),
('n1-3551','2027-01-20','連合','れんごう','연합; 둘 이상의 조직이나 집단이 결합함','二つ以上の組織や集団が共通の目的で結び付くこと。','複数の団体が連合して、共同の提案を政府に提出した。','여러 단체가 연합해 공동 제안을 정부에 제출했다.'),
('n1-3552','2027-01-20','普及','ふきゅう','보급; 널리 퍼져 일반적으로 사용됨','広く行き渡り、多くの人に使われるようになること。','通信技術の普及によって働き方の選択肢が広がった。','통신 기술의 보급으로 일하는 방식의 선택지가 넓어졌다.'),
('n1-3553','2027-01-20','複数','ふくすう','복수; 둘 이상의 수나 대상','数が二つ以上であること。','重要な判断では複数の資料を照合する必要がある。','중요한 판단에서는 여러 자료를 대조할 필요가 있다.'),
('n1-3554','2027-01-20','符号','ふごう','부호; 의미나 정보를 나타내는 기호','意味や情報を表すために用いる記号。','図中の符号が何を示すかを凡例で確認した。','그림 속 부호가 무엇을 나타내는지 범례에서 확인했다.'),
('n1-3555','2027-01-20','物騒','ぶっそう','위험하고 불안함; 사건이 일어날 듯 흉흉함','事件や危険が起こりそうで、不安なさま。','物騒な事件が続き、地域では警戒が強まっている。','흉흉한 사건이 이어져 지역의 경계가 강화되고 있다.'),
('n1-3556','2027-01-20','文芸','ぶんげい','문예; 문학과 예술, 특히 언어로 표현하는 예술','文学を中心とする芸術、特に言葉によって表現する芸術。','地域の文芸を紹介する雑誌が創刊された。','지역 문예를 소개하는 잡지가 창간되었다.'),
('n1-3557','2027-01-20','文献','ぶんけん','문헌; 연구나 조사에서 참고하는 기록과 자료','研究や調査の根拠・参考となる記録や資料。','先行研究の文献を調べ、議論の経緯を整理した。','선행 연구 문헌을 조사해 논의의 경위를 정리했다.'),
('n1-3558','2027-01-20','文体','ぶんたい','문체; 글에 드러나는 표현상의 특징','文章に表れる語句の選び方や表現上の特徴。','同じ内容でも文体によって読者が受ける印象は変わる。','같은 내용이라도 문체에 따라 독자가 받는 인상은 달라진다.'),
('n1-3559','2027-01-20','文脈','ぶんみゃく','문맥; 앞뒤 말이나 상황이 이루는 의미의 흐름','文章や会話の前後関係から成り立つ意味の流れ。','一つの表現だけを切り離さず、文脈の中で意味を判断する。','한 표현만 떼어 내지 않고 문맥 속에서 의미를 판단한다.'),
('n1-3560','2027-01-20','標本','ひょうほん','표본; 전체의 성질을 조사하기 위해 뽑은 일부; 보존한 견본','全体の性質を調べるために取り出した一部。また、観察用に保存した見本。','偏りの少ない標本を集めなければ、調査結果の信頼性は下がる。','편향이 적은 표본을 모으지 않으면 조사 결과의 신뢰성이 낮아진다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2027-01-07..2027-01-20' FROM _n1_b8_words_0123 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b8_map_0123(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b8_words_0123 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
