INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3281","prompt":"「体系」の読み方として最も適切なものを選びなさい。","options":["りゅういき","せいさく","へいこう","たいけい"],"answer":"たいけい","explanationKo":"「体系」는 「たいけい」라고 읽는다. 뜻은 체계; 서로 관련된 요소가 일정한 원리에 따라 조직된 전체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3282","prompt":"「素質」の読み方として最も適切なものを選びなさい。","options":["しんしん","むげん","そしつ","ちょぞう"],"answer":"そしつ","explanationKo":"「素質」는 「そしつ」라고 읽는다. 뜻은 소질; 타고난 성질이나 잠재 능력이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3283","prompt":"「超過」の読み方として最も適切なものを選びなさい。","options":["みぶん","ちょうか","だんてい","じゅうきょ"],"answer":"ちょうか","explanationKo":"「超過」는 「ちょうか」라고 읽는다. 뜻은 초과; 정해진 한도나 수량을 넘어섬이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3284","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその説明は専門家には（　）しても、一般の利用者には分かりにくい。","options":["通用","法則","臨時","整備"],"answer":"通用","explanationKo":"문맥상 「通用」가 가장 자연스럽다. 통용; 널리 받아들여져 사용됨; 효력이 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3285","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n安全性を確保するため、国際（　）に沿って設計した。","options":["人命","無数","文脈","標準"],"answer":"標準","explanationKo":"문맥상 「標準」가 가장 자연스럽다. 표준; 판단이나 측정의 기준이 되는 것라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3286","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n大量の資料を短期間で（　）するには、要点を見極める必要がある。","options":["未満","文芸","消化","資料"],"answer":"消化","explanationKo":"문맥상 「消化」가 가장 자연스럽다. 소화; 음식물을 흡수 가능한 상태로 만듦; 내용을 충분히 이해함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3287","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n実験条件に合わせて専用の測定装置を（　）した。","options":["募集","作製","例外","成立"],"answer":"作製","explanationKo":"문맥상 「作製」가 가장 자연스럽다. 제작; 기계나 도구 같은 물건을 실제로 만듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3288","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害後、（　）を失った人への支援が急がれた。","options":["住居","迷信","標本","増大"],"answer":"住居","explanationKo":"문맥상 「住居」가 가장 자연스럽다. 주거; 사람이 생활하는 집이나 장소라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3289","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の（　）を照合し、記述の正確性を確認した。","options":["宣伝","輸送","中途","資料"],"answer":"資料","explanationKo":"문맥상 「資料」가 가장 자연스럽다. 자료; 조사·연구·판단의 근거가 되는 정보나 문서라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3290","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長時間の勤務は（　）に大きな負担を及ぼす。","options":["要旨","作製","心身","相互"],"answer":"心身","explanationKo":"문맥상 「心身」가 가장 자연스럽다. 심신; 마음과 몸라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3291","prompt":"「許可や手続きなどを公的な機関に申し出ること。」という意味に最も近い語を選びなさい。","options":["超過","申請","先端","目安"],"answer":"申請","explanationKo":"「申請」의 핵심 의미는 신청; 허가나 처리를 공식적으로 요청함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3292","prompt":"「状態を調べ、病気や問題の原因・性質を判断すること。」という意味に最も近い語を選びなさい。","options":["診断","文体","増減","普及"],"answer":"診断","explanationKo":"「診断」의 핵심 의미는 진단; 상태를 조사하여 질병이나 문제의 원인을 판단함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3293","prompt":"「人の生命。」という意味に最も近い語を選びなさい。","options":["用途","申請","貯蔵","人命"],"answer":"人命","explanationKo":"「人命」의 핵심 의미는 인명; 사람의 생명이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3294","prompt":"「分かっている事実を基に、数量や状態を推し量ること。」という意味に最も近い語を選びなさい。","options":["通用","断定","推定","友好"],"answer":"推定","explanationKo":"「推定」의 핵심 의미는 추정; 알려진 사실을 바탕으로 수치나 상태를 미루어 판단함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3295","prompt":"「機械・製品・道具などを作ること。」という意味に最も近い語を選びなさい。","options":["法則","製作","増大","体系"],"answer":"製作","explanationKo":"「製作」의 핵심 의미는 제작; 기계·제품·도구 등을 만듦이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','grammar',1,'〜をもって','{"pattern":"〜をもって","meaningKo":"〜을 기해; 〜으로써","explanation":"〜をもって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"本日の受付をもって、今年度の募集を終了します。","ko":"문맥에서 〜을 기해; 〜으로써의 의미로 쓰였다."},{"ja":"この結果をもって、計画全体が成功したとは断定できない。","ko":"이 문장도 〜을 기해; 〜으로써의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','grammar',2,'〜をおいて','{"pattern":"〜をおいて","meaningKo":"〜외에는; 〜을 두고","explanation":"〜をおいて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"この役割を任せられる人は、彼をおいてほかにいない。","ko":"문맥에서 〜외에는; 〜을 두고의 의미로 쓰였다."},{"ja":"現場を熟知した彼女をおいて、適任者は考えられない。","ko":"이 문장도 〜외에는; 〜을 두고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本日の受付（　）、今年度の募集を終了します。","options":["〜をもって","〜に応じて","〜のみならず","〜ものを"],"answer":"〜をもって","explanationKo":"문맥상 〜을 기해; 〜으로써를 나타내는 「〜をもって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの役割を任せられる人は、彼（　）ほかにいない。","options":["〜に伴って","〜も同然だ","〜にあたって","〜をおいて"],"answer":"〜をおいて","explanationKo":"문맥상 〜외에는; 〜을 두고를 나타내는 「〜をおいて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n過去の失敗（　）、確認項目を追加した。","options":["〜ないものでもない","〜に際して","〜を踏まえて","〜にかかわる"],"answer":"〜を踏まえて","explanationKo":"문맥상 〜을 바탕으로를 나타내는 「〜を踏まえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-07','reading',1,'分類の基準を先に決める','{"passage":"大量の情報を種類ごとに整理することには、共通点と相違点を把握しやすくなることという利点がある。しかし、作業の途中で基準を変えると同じ情報が別の集団に入ることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、目的に合う分類基準を先に定めて一貫して適用することが重要なのである。","questions":[{"prompt":"「分類の基準を先に決める」について筆者が最も重視していることは何か。","options":["目的に合う分類基準を先に定めて一貫して適用すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"目的に合う分類基準を先に定めて一貫して適用すること","explanationKo":"본문에서는 目的に合う分類基準を先に定めて一貫して適用すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["作業の途中で基準を変えると同じ情報が別の集団に入ること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"作業の途中で基準を変えると同じ情報が別の集団に入ること","explanationKo":"주의할 점은 作業の途中で基準を変えると同じ情報が別の集団に入ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["共通点と相違点を把握しやすくなること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"共通点と相違点を把握しやすくなること","explanationKo":"大量の情報を種類ごとに整理すること에는 共通点と相違点を把握しやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3301","prompt":"「接近」の読み方として最も適切なものを選びなさい。","options":["せっきん","ちょぞう","しんしん","みんかん"],"answer":"せっきん","explanationKo":"「接近」는 「せっきん」라고 읽는다. 뜻은 접근; 가까이 다가감이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3302","prompt":"「接続」の読み方として最も適切なものを選びなさい。","options":["まさつ","ふくすう","せいりつ","せつぞく"],"answer":"せつぞく","explanationKo":"「接続」는 「せつぞく」라고 읽는다. 뜻은 접속; 둘 이상의 것을 이어 연결함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3303","prompt":"「先端」の読み方として最も適切なものを選びなさい。","options":["めやす","ちょうか","せんたん","せいとう"],"answer":"せんたん","explanationKo":"「先端」는 「せんたん」라고 읽는다. 뜻은 선단; 맨 앞끝; 가장 앞선 분야이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3304","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n効果だけを強調して（　）すると、利用者に誤解を与えかねない。","options":["文体","宣伝","人命","無限"],"answer":"宣伝","explanationKo":"문맥상 「宣伝」가 가장 자연스럽다. 선전; 널리 알리거나 지지를 얻기 위해 정보를 퍼뜨림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3305","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度（　）を見直し、重複した手続きを削減した。","options":["全般","未満","損得","用途"],"answer":"全般","explanationKo":"문맥상 「全般」가 가장 자연스럽다. 전반; 어떤 범위의 전체라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3306","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n報告書と実際の記録には重大な（　）が見つかった。","options":["防止","全般","友好","相違"],"answer":"相違","explanationKo":"문맥상 「相違」가 가장 자연스럽다. 상위; 서로 같지 않고 차이가 있음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3307","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者数の（　）を月ごとに比較した。","options":["文脈","増大","増減","無数"],"answer":"増減","explanationKo":"문맥상 「増減」가 가장 자연스럽다. 증감; 늘거나 줄어듦라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3308","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）の立場を理解することが合意形成の第一歩となる。","options":["診断","相互","段階","要領"],"answer":"相互","explanationKo":"문맥상 「相互」가 가장 자연스럽다. 상호; 양쪽이 서로 관계함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3309","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n需要の（　）に伴い、供給体制の拡充が求められた。","options":["増大","相互","用語","消化"],"answer":"増大","explanationKo":"문맥상 「増大」가 가장 자연스럽다. 증대; 수량이나 정도가 크게 늘어남라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3310","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n同じ条件で温度を（　）し、結果の差を比較した。","options":["標本","増大","素質","測定"],"answer":"測定","explanationKo":"문맥상 「測定」가 가장 자연스럽다. 측정; 기구나 기준을 이용해 수치로 나타냄라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3311","prompt":"「損失と利益、または損か得かということ。」という意味に最も近い語を選びなさい。","options":["推定","分類","損得","予備"],"answer":"損得","explanationKo":"「損得」의 핵심 의미는 손익; 손해와 이익이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3312","prompt":"「意見や立場などが互いに反対し、ぶつかり合うこと。」という意味に最も近い語を選びなさい。","options":["貯蔵","対立","要旨","作製"],"answer":"対立","explanationKo":"「対立」의 핵심 의미는 대립; 의견이나 입장이 맞서 충돌함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3313","prompt":"「判断や方法が状況に合っており、合理的であること。」という意味に最も近い語を選びなさい。","options":["妥当","溜める","兼ねる","接する"],"answer":"妥当","explanationKo":"「妥当」의 핵심 의미는 타당; 판단이나 방법이 상황에 알맞고 합리적임이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3314","prompt":"「物事の進行過程で区切られる順序や程度。」という意味に最も近い語を選びなさい。","options":["製作","並行","政党","段階"],"answer":"段階","explanationKo":"「段階」의 핵심 의미는 단계; 진행 과정에서 구분되는 순서나 수준이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3315","prompt":"「物事をはっきりそうだと決めつけること。」という意味に最も近い語を選びなさい。","options":["分布","人命","断定","申請"],"answer":"断定","explanationKo":"「断定」의 핵심 의미는 단정; 충분한 여지를 두지 않고 확실하다고 판단함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','grammar',1,'〜を踏まえて','{"pattern":"〜を踏まえて","meaningKo":"〜을 바탕으로","explanation":"〜を踏まえて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"利用者の意見を踏まえて、申請手続きを簡素化した。","ko":"문맥에서 〜을 바탕으로의 의미로 쓰였다."},{"ja":"過去の失敗を踏まえて、確認項目を追加した。","ko":"이 문장도 〜을 바탕으로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','grammar',2,'〜に基づいて','{"pattern":"〜に基づいて","meaningKo":"〜에 근거하여","explanation":"〜に基づいて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"客観的な資料に基づいて、支援の優先順位を決める。","ko":"문맥에서 〜에 근거하여의 의미로 쓰였다."},{"ja":"契約の条件に基づいて、費用を算定した。","ko":"이 문장도 〜에 근거하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n利用者の意見（　）、申請手続きを簡素化した。","options":["〜にかかわる","〜ないものでもない","〜に際して","〜を踏まえて"],"answer":"〜を踏まえて","explanationKo":"문맥상 〜을 바탕으로를 나타내는 「〜を踏まえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n客観的な資料（　）、支援の優先順位を決める。","options":["〜ずじまい","〜を前提として","〜に基づいて","〜をめぐって"],"answer":"〜に基づいて","explanationKo":"문맥상 〜에 근거하여를 나타내는 「〜に基づいて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n川の流れ（　）、避難経路が整備された。","options":["〜に限ったことではない","〜に沿って","〜を通じて","〜っぱなし"],"answer":"〜に沿って","explanationKo":"문맥상 〜에 따라서를 나타내는 「〜に沿って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-08','reading',1,'並行作業の接点を管理する','{"passage":"複数の作業を同時に進めることには、全体の期間を短縮できることという利点がある。しかし、一方の変更が他方に伝わらなければ手戻りが生じることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、相互に影響する時点と共有事項を明確にすることが重要なのである。","questions":[{"prompt":"「並行作業の接点を管理する」について筆者が最も重視していることは何か。","options":["相互に影響する時点と共有事項を明確にすること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"相互に影響する時点と共有事項を明確にすること","explanationKo":"본문에서는 相互に影響する時点と共有事項を明確にすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["一方の変更が他方に伝わらなければ手戻りが生じること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"一方の変更が他方に伝わらなければ手戻りが生じること","explanationKo":"주의할 점은 一方の変更が他方に伝わらなければ手戻りが生じること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["全体の期間を短縮できること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"全体の期間を短縮できること","explanationKo":"複数の作業を同時に進めること에는 全体の期間を短縮できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3321","prompt":"「承る」の読み方として最も適切なものを選びなさい。","options":["かたまる","うけたまわる","くやむ","あむ"],"answer":"うけたまわる","explanationKo":"「承る」는 「うけたまわる」라고 읽는다. 뜻은 삼가 듣다; 받다; 맡다의 겸양 표현이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3322","prompt":"「補う」の読み方として最も適切なものを選びなさい。","options":["おぎなう","かく","みまう","とりけす"],"answer":"おぎなう","explanationKo":"「補う」는 「おぎなう」라고 읽는다. 뜻은 보충하다; 부족한 부분을 채우다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3323","prompt":"「怠る」の読み方として最も適切なものを選びなさい。","options":["つりあう","ひきだす","くむ","おこたる"],"answer":"おこたる","explanationKo":"「怠る」는 「おこたる」라고 읽는다. 뜻은 게을리하다; 해야 할 일을 소홀히 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3324","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査結果を踏まえ、従来の方針を（　）ことにした。","options":["見直す","飛び込む","改める","帰す"],"answer":"改める","explanationKo":"문맥상 「改める」가 가장 자연스럽다. 고치다; 새롭게 바꾸다; 다시 확인하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3325","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n研究成果を専門書として（　）ことが彼の長年の目標だった。","options":["焦げる","著す","散らかる","揃える"],"answer":"著す","explanationKo":"문맥상 「著す」가 가장 자연스럽다. 저술하다; 책이나 글을 쓰다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3326","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n両社が新技術の主導権を（　）構図になっている。","options":["争う","枯れる","腰掛ける","溜める"],"answer":"争う","explanationKo":"문맥상 「争う」가 가장 자연스럽다. 다투다; 경쟁하다; 사실 여부를 문제 삼다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3327","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n異なる文化を（　）姿勢が相互理解につながる。","options":["零れる","遡る","討つ","敬う"],"answer":"敬う","explanationKo":"문맥상 「敬う」가 가장 자연스럽다. 공경하다; 존경하는 마음으로 대하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3328","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n国を（　）者には公平な判断が求められる。","options":["気を付ける","怠る","治める","近付ける"],"answer":"治める","explanationKo":"문맥상 「治める」가 가장 자연스럽다. 다스리다; 질서 있게 통치하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3329","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n一方の意見に（　）前に、反対の根拠も確認すべきだ。","options":["突き当たる","傾く","見舞う","取り消す"],"answer":"傾く","explanationKo":"문맥상 「傾く」가 가장 자연스럽다. 기울다; 한쪽 방향이나 상태로 치우치다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3330","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの施設は地域交流の場と災害時の避難所を（　）。","options":["兼ねる","余る","重なる","目立つ"],"answer":"兼ねる","explanationKo":"문맥상 「兼ねる」가 가장 자연스럽다. 겸하다; 두 가지 이상의 역할을 함께 맡다; 하기 어렵다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3331","prompt":"「細かく切る、文字などを彫る。また、時間や変化を積み重ねる。」という意味に最も近い語を選びなさい。","options":["静まる","点く","縮める","刻む"],"answer":"刻む","explanationKo":"「刻む」의 핵심 의미는 새기다; 잘게 썰다; 시간이나 변화를 차곡차곡 기록하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3332","prompt":"「まとまった形や均衡を壊す。」という意味に最も近い語を選びなさい。","options":["焦げる","見つける","崩す","揃える"],"answer":"崩す","explanationKo":"「崩す」의 핵심 의미는 무너뜨리다; 균형이나 형식을 깨뜨리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3333","prompt":"「まとまった形や均衡が壊れる。」という意味に最も近い語を選びなさい。","options":["薄める","崩れる","茂る","散る"],"answer":"崩れる","explanationKo":"「崩れる」의 핵심 의미는 무너지다; 균형이나 질서가 깨지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3334","prompt":"「固い物を細かく壊す。また、難しい内容を分かりやすくする。」という意味に最も近い語を選びなさい。","options":["砕く","遡る","討つ","渇く"],"answer":"砕く","explanationKo":"「砕く」의 핵심 의미는 부수다; 잘게 깨다; 어려운 내용을 쉽게 풀다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3335","prompt":"「細かく壊れる。また、態度や表現が堅苦しくなくなる。」という意味に最も近い語を選びなさい。","options":["気を付ける","怠る","接する","砕ける"],"answer":"砕ける","explanationKo":"「砕ける」의 핵심 의미는 부서지다; 딱딱한 태도나 표현이 부드러워지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','grammar',1,'〜に沿って','{"pattern":"〜に沿って","meaningKo":"〜에 따라서","explanation":"〜に沿って는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"合意した方針に沿って、各部署が作業を進めている。","ko":"문맥에서 〜에 따라서의 의미로 쓰였다."},{"ja":"川の流れに沿って、避難経路が整備された。","ko":"이 문장도 〜에 따라서의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','grammar',2,'〜に応じて','{"pattern":"〜に応じて","meaningKo":"〜에 따라; 〜에 맞추어","explanation":"〜に応じて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"利用者の状況に応じて、説明の方法を変える必要がある。","ko":"문맥에서 〜에 따라; 〜에 맞추어의 의미로 쓰였다."},{"ja":"需要の変化に応じて、生産量を調整した。","ko":"이 문장도 〜에 따라; 〜에 맞추어의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n合意した方針（　）、各部署が作業を進めている。","options":["〜っぱなし","〜に限ったことではない","〜に沿って","〜を通じて"],"answer":"〜に沿って","explanationKo":"문맥상 〜에 따라서를 나타내는 「〜に沿って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n利用者の状況（　）、説明の方法を変える必要がある。","options":["〜を問わず","〜に応じて","〜にとどまらず","〜に堪えない"],"answer":"〜に応じて","explanationKo":"문맥상 〜에 따라; 〜에 맞추어를 나타내는 「〜に応じて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n人口の増加（　）、交通の混雑が深刻になった。","options":["〜に伴って","〜のみならず","〜てならない","〜に限らず"],"answer":"〜に伴って","explanationKo":"문맥상 〜에 따라; 〜와 함께를 나타내는 「〜に伴って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-09','reading',1,'編集で原文の意図を守る','{"passage":"複数の文章を読みやすくまとめることには、読者に要点を伝えやすくなることという利点がある。しかし、表現を整える過程で書き手の条件や留保を消すことに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、変更箇所と編集理由を確認できるようにすることが重要なのである。","questions":[{"prompt":"「編集で原文の意図を守る」について筆者が最も重視していることは何か。","options":["変更箇所と編集理由を確認できるようにすること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"変更箇所と編集理由を確認できるようにすること","explanationKo":"본문에서는 変更箇所と編集理由を確認できるようにすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["表現を整える過程で書き手の条件や留保を消すこと","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"表現を整える過程で書き手の条件や留保を消すこと","explanationKo":"주의할 점은 表現を整える過程で書き手の条件や留保を消すこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["読者に要点を伝えやすくなること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"読者に要点を伝えやすくなること","explanationKo":"複数の文章を読みやすくまとめること에는 読者に要点を伝えやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3341","prompt":"「探る」の読み方として最も適切なものを選びなさい。","options":["しばる","うつる","さぐる","ためる"],"answer":"さぐる","explanationKo":"「探る」는 「さぐる」라고 읽는다. 뜻은 탐색하다; 숨겨진 사정이나 가능성을 알아보다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3342","prompt":"「囁く」の読み方として最も適切なものを選びなさい。","options":["うちけす","ささやく","うつ","かわく"],"answer":"ささやく","explanationKo":"「囁く」는 「ささやく」라고 읽는다. 뜻은 속삭이다; 작은 목소리로 말하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3343","prompt":"「妨げる」の読み方として最も適切なものを選びなさい。","options":["さまたげる","おこたる","せっする","うつる"],"answer":"さまたげる","explanationKo":"「妨げる」는 「さまたげる」라고 읽는다. 뜻은 방해하다; 진행이나 실현을 가로막다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3344","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n細かい規則で現場の判断を（　）べきではない。","options":["突き当たる","擦る","焚く","縛る"],"answer":"縛る","explanationKo":"문맥상 「縛る」가 가장 자연스럽다. 묶다; 규칙이나 조건으로 자유를 제한하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3345","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の案から実現可能な三案に候補を（　）。","options":["治める","飢える","絞る","刷る"],"answer":"絞る","explanationKo":"문맥상 「絞る」가 가장 자연스럽다. 짜다; 범위나 대상을 좁히다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3346","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度の変更によって新たな負担が（　）可能性がある。","options":["助かる","生ずる","憧れる","捜す"],"answer":"生ずる","explanationKo":"문맥상 「生ずる」가 가장 자연스럽다. 생기다; 발생하다; 만들어 내다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3347","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多様な価値観に（　）ことで、考え方の幅が広がった。","options":["接する","剃る","属する","砕ける"],"answer":"接する","explanationKo":"문맥상 「接する」가 가장 자연스럽다. 접하다; 맞닿다; 사람이나 정보와 마주하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3348","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n回答期限が（　）中、早急な判断が求められた。","options":["囁く","映る","仕上がる","迫る"],"answer":"迫る","explanationKo":"문맥상 「迫る」가 가장 자연스럽다. 다가오다; 강하게 요구하다; 임박하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3349","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n守りに入るだけでなく、新しい市場を積極的に（　）方針だ。","options":["敬う","揃う","攻める","挙げる"],"answer":"攻める","explanationKo":"문맥상 「攻める」가 가장 자연스럽다. 공격하다; 적극적으로 공략하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3350","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの権限は地方自治体ではなく国に（　）。","options":["釣り合う","属する","焦がす","見舞う"],"answer":"属する","explanationKo":"문맥상 「属する」가 가장 자연스럽다. 속하다; 어떤 집단이나 범주에 포함되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3351","prompt":"「進むべき方向や本来の話題から外れる。」という意味に最も近い語を選びなさい。","options":["逸れる","乾かす","受け持つ","ひっくり返る"],"answer":"逸れる","explanationKo":"「逸れる」의 핵심 의미는 벗어나다; 방향이나 주제에서 빗나가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3352","prompt":"「必要なものが全部集まる。また、形や状態が一致する。」という意味に最も近い語を選びなさい。","options":["治める","飢える","見慣れる","揃う"],"answer":"揃う","explanationKo":"「揃う」의 핵심 의미는 갖추어지다; 전부 모이다; 서로 일치하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3353","prompt":"「必要なものを集める。また、形や条件を同じにする。」という意味に最も近い語を選びなさい。","options":["炊く","砕ける","揃える","越す"],"answer":"揃える","explanationKo":"「揃える」의 핵심 의미는 갖추다; 모으다; 같은 상태로 맞추다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3354","prompt":"「水準や程度をより高くする。」という意味に最も近い語を選びなさい。","options":["話し掛ける","高める","治める","代える"],"answer":"高める","explanationKo":"「高める」의 핵심 의미는 높이다; 수준이나 정도를 향상시키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3355","prompt":"「金銭・知識・資源・力などを少しずつためておく。」という意味に最も近い語を選びなさい。","options":["蓄える","追い掛ける","応じる","崩す"],"answer":"蓄える","explanationKo":"「蓄える」의 핵심 의미는 저축하다; 지식·자원·힘 등을 모아 두다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','grammar',1,'〜に伴って','{"pattern":"〜に伴って","meaningKo":"〜에 따라; 〜와 함께","explanation":"〜に伴って는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"制度の変更に伴って、申請書の様式も改められた。","ko":"문맥에서 〜에 따라; 〜와 함께의 의미로 쓰였다."},{"ja":"人口の増加に伴って、交通の混雑が深刻になった。","ko":"이 문장도 〜에 따라; 〜와 함께의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','grammar',2,'〜にかかわる','{"pattern":"〜にかかわる","meaningKo":"〜와 관련된; 〜에 영향을 미치는","explanation":"〜にかかわる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"人命にかかわる情報は、確認後ただちに共有すべきだ。","ko":"문맥에서 〜와 관련된; 〜에 영향을 미치는의 의미로 쓰였다."},{"ja":"将来の方針にかかわる重要な議論が行われた。","ko":"이 문장도 〜와 관련된; 〜에 영향을 미치는의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n制度の変更（　）、申請書の様式も改められた。","options":["〜に限らず","〜に伴って","〜のみならず","〜てならない"],"answer":"〜に伴って","explanationKo":"문맥상 〜에 따라; 〜와 함께를 나타내는 「〜に伴って」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n人命（　）情報は、確認後ただちに共有すべきだ。","options":["〜にかかわる","〜も同然だ","〜とみえて","〜ならいざ知らず"],"answer":"〜にかかわる","explanationKo":"문맥상 〜와 관련된; 〜에 영향을 미치는를 나타내는 「〜にかかわる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n責任の所在（　）、長い協議が続いた。","options":["〜ないものでもない","〜ものを","〜とあっては","〜をめぐって"],"answer":"〜をめぐって","explanationKo":"문맥상 〜을 둘러싸고를 나타내는 「〜をめぐって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-10','reading',1,'再発防止を個人の注意で終えない','{"passage":"事故の原因を調べて対策することには、同じ種類の問題を減らせることという利点がある。しかし、注意を求めるだけでは作業環境の欠陥が残ることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、手順と設備と情報共有の仕組みまで見直すことが重要なのである。","questions":[{"prompt":"「再発防止を個人の注意で終えない」について筆者が最も重視していることは何か。","options":["手順と設備と情報共有の仕組みまで見直すこと","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"手順と設備と情報共有の仕組みまで見直すこと","explanationKo":"본문에서는 手順と設備と情報共有の仕組みまで見直すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["注意を求めるだけでは作業環境の欠陥が残ること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"注意を求めるだけでは作業環境の欠陥が残ること","explanationKo":"주의할 점은 注意を求めるだけでは作業環境の欠陥が残ること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["同じ種類の問題を減らせること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"同じ種類の問題を減らせること","explanationKo":"事故の原因を調べて対策すること에는 同じ種類の問題を減らせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3361","prompt":"「味わう」の読み方として最も適切なものを選びなさい。","options":["まちあわせる","あらそう","ちかう","あじわう"],"answer":"あじわう","explanationKo":"「味わう」는 「あじわう」라고 읽는다. 뜻은 맛보다; 직접 경험하며 깊이 느끼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3362","prompt":"「預かる」の読み方として最も適切なものを選びなさい。","options":["うらやむ","ながびく","あずかる","せまる"],"answer":"あずかる","explanationKo":"「預かる」는 「あずかる」라고 읽는다. 뜻은 맡다; 보관하다; 책임지고 관리하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3363","prompt":"「暴れる」の読み方として最も適切なものを選びなさい。","options":["ちぢむ","あばれる","おうじる","くずす"],"answer":"あばれる","explanationKo":"「暴れる」는 「あばれる」라고 읽는다. 뜻은 난폭하게 굴다; 거세게 날뛰다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3364","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n部下を（　）ことと、失敗から学ぶ機会を与えることは違う。","options":["甘やかす","威張る","呼び出す","挿す"],"answer":"甘やかす","explanationKo":"문맥상 「甘やかす」가 가장 자연스럽다. 응석을 받아주다; 지나치게 관대하게 대하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3365","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予算が（　）からといって、不要な支出を増やすべきではない。","options":["捜す","建つ","生ずる","余る"],"answer":"余る","explanationKo":"문맥상 「余る」가 가장 자연스럽다. 남다; 필요량이나 한도를 넘다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3366","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n研究成果を一冊の事典に（　）作業が進められている。","options":["埋める","組み立てる","編む","砕ける"],"answer":"編む","explanationKo":"문맥상 「編む」가 가장 자연스럽다. 뜨다; 엮다; 자료를 모아 책으로 만들다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3367","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n本人が（　）方法を無理に押し付けてはいけない。","options":["刻む","嫌がる","見慣れる","憧れる"],"answer":"嫌がる","explanationKo":"문맥상 「嫌がる」가 가장 자연스럽다. 싫어하다; 싫다는 태도를 보이다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3368","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n紛争によって多くの住民が食料に（　）状況が続いている。","options":["飢える","砕ける","枯れる","腰掛ける"],"answer":"飢える","explanationKo":"문맥상 「飢える」가 가장 자연스럽다. 굶주리다; 필요한 것이 몹시 부족하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3369","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼女は安堵の表情を（　）と、静かに席を立った。","options":["話し掛ける","零れる","削る","浮かべる"],"answer":"浮かべる","explanationKo":"문맥상 「浮かべる」가 가장 자연스럽다. 띄우다; 표정이나 생각을 드러내다; 떠올리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3370","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n根拠のない提案は現場の実情から（　）おそれがある。","options":["片付く","暖まる","浮く","思い付く"],"answer":"浮く","explanationKo":"문맥상 「浮く」가 가장 자연스럽다. 뜨다; 고정되지 않다; 주변과 어울리지 않다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3371","prompt":"「液体の濃度や物事の程度を低くする。」という意味に最も近い語を選びなさい。","options":["透き通る","薄める","恨む","近寄る"],"answer":"薄める","explanationKo":"「薄める」의 핵심 의미는 묽게 하다; 농도나 정도를 낮추다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3372","prompt":"「敵や悪者を攻めて倒す。」という意味に最も近い語を選びなさい。","options":["討つ","建つ","生ずる","重ねる"],"answer":"討つ","explanationKo":"「討つ」의 핵심 의미는 토벌하다; 공격하여 쓰러뜨리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3373","prompt":"「光や映像によって、物の姿を画面や鏡などに表す。」という意味に最も近い語を選びなさい。","options":["埋める","組み立てる","押さえる","映す"],"answer":"映す","explanationKo":"「映す」의 핵심 의미는 비추다; 영상이나 모습을 화면에 나타내다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3374","prompt":"「写真や映像の中に姿が記録される。」という意味に最も近い語を選びなさい。","options":["刻む","預かる","写る","憧れる"],"answer":"写る","explanationKo":"「写る」의 핵심 의미는 찍히다; 사진이나 영상에 나타나다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3375","prompt":"「鏡・水面・画面・目などに姿や映像が現れる。」という意味に最も近い語を選びなさい。","options":["見下ろす","映る","誓う","卸す"],"answer":"映る","explanationKo":"「映る」의 핵심 의미는 비치다; 화면이나 눈에 모습이 나타나다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','grammar',1,'〜をめぐって','{"pattern":"〜をめぐって","meaningKo":"〜을 둘러싸고","explanation":"〜をめぐって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"新しい開発計画をめぐって、住民の意見が分かれている。","ko":"문맥에서 〜을 둘러싸고의 의미로 쓰였다."},{"ja":"責任の所在をめぐって、長い協議が続いた。","ko":"이 문장도 〜을 둘러싸고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','grammar',2,'〜を通じて','{"pattern":"〜を通じて","meaningKo":"〜을 통해","explanation":"〜を通じて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"地域活動を通じて、世代の異なる人々が交流した。","ko":"문맥에서 〜을 통해의 의미로 쓰였다."},{"ja":"調査を通じて、制度上の課題が明らかになった。","ko":"이 문장도 〜을 통해의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n新しい開発計画（　）、住民の意見が分かれている。","options":["〜をめぐって","〜ないものでもない","〜ものを","〜とあっては"],"answer":"〜をめぐって","explanationKo":"문맥상 〜을 둘러싸고를 나타내는 「〜をめぐって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n地域活動（　）、世代の異なる人々が交流した。","options":["〜ずじまい","〜にあたって","〜をもって","〜を通じて"],"answer":"〜を通じて","explanationKo":"문맥상 〜을 통해를 나타내는 「〜を通じて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの技術は医療（　）、教育にも応用されている。","options":["〜に際して","〜をおいて","〜にとどまらず","〜っぱなし"],"answer":"〜にとどまらず","explanationKo":"문맥상 〜에 그치지 않고를 나타내는 「〜にとどまらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-11','reading',1,'方針と例外を同時に示す','{"passage":"組織の基本的な判断方向を定めることには、担当者が一貫した対応を選びやすくなることという利点がある。しかし、例外条件がなければ特殊な事例に無理な適用が起きることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、原則に加えて例外と承認手順を明文化することが重要なのである。","questions":[{"prompt":"「方針と例外を同時に示す」について筆者が最も重視していることは何か。","options":["原則に加えて例外と承認手順を明文化すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"原則に加えて例外と承認手順を明文化すること","explanationKo":"본문에서는 原則に加えて例外と承認手順を明文化すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["例外条件がなければ特殊な事例に無理な適用が起きること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"例外条件がなければ特殊な事例に無理な適用が起きること","explanationKo":"주의할 점은 例外条件がなければ特殊な事例に無理な適用が起きること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["担当者が一貫した対応を選びやすくなること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"担当者が一貫した対応を選びやすくなること","explanationKo":"組織の基本的な判断方向を定めること에는 担当者が一貫した対応を選びやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3381","prompt":"「納める」の読み方として最も適切なものを選びなさい。","options":["おさめる","さす","たまる","たかめる"],"answer":"おさめる","explanationKo":"「納める」는 「おさめる」라고 읽는다. 뜻은 납부하다; 거두어 넣다; 일정한 자리에 수납하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3382","prompt":"「驚かす」の読み方として最も適切なものを選びなさい。","options":["きざむ","あずかる","かぐ","おどろかす"],"answer":"おどろかす","explanationKo":"「驚かす」는 「おどろかす」라고 읽는다. 뜻은 놀라게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3383","prompt":"「卸す」の読み方として最も適切なものを選びなさい。","options":["みおろす","とけこむ","おろす","おどろかす"],"answer":"おろす","explanationKo":"「卸す」는 「おろす」라고 읽는다. 뜻은 도매로 넘기다; 새 물건을 처음 사용하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3384","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n問題の原因を個人の能力だけに（　）のは適切ではない。","options":["次ぐ","帰す","立ち止まる","付き合う"],"answer":"帰す","explanationKo":"문맥상 「帰す」가 가장 자연스럽다. 돌려보내다; 어떤 원인이나 책임으로 돌리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3385","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n対面会議をオンライン形式に（　）ことになった。","options":["代える","驚かす","見送る","釣り合う"],"answer":"代える","explanationKo":"문맥상 「代える」가 가장 자연스럽다. 대신하게 하다; 다른 것으로 교체하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3386","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n傷口を（　）と症状が悪化するおそれがある。","options":["足る","属する","着せる","掻く"],"answer":"掻く","explanationKo":"문맥상 「掻く」가 가장 자연스럽다. 긁다; 휘저어 모으다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3387","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n異臭を（　）場合は、直ちにその場を離れてください。","options":["引き止める","錆びる","嗅ぐ","重ねる"],"answer":"嗅ぐ","explanationKo":"문맥상 「嗅ぐ」가 가장 자연스럽다. 냄새를 맡다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3388","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の要因が（　）ことで、被害が拡大した。","options":["編む","重なる","押さえる","悔やむ"],"answer":"重なる","explanationKo":"문맥상 「重なる」가 가장 자연스럽다. 겹치다; 여러 일이 동시에 일어나다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3389","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n議論を（　）中で、双方の立場の違いが明確になった。","options":["重ねる","焦げる","見つける","承る"],"answer":"重ねる","explanationKo":"문맥상 「重ねる」가 가장 자연스럽다. 겹치다; 반복해서 쌓다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3390","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n具体的な方針が（　）まで、発表は控えることにした。","options":["見下ろす","溶け込む","振る舞う","固まる"],"answer":"固まる","explanationKo":"문맥상 「固まる」가 가장 자연스럽다. 굳다; 의견이나 방침이 확정되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3391","prompt":"「肩に載せて運ぶ。また、人を持ち上げたり、だましたりする。」という意味に最も近い語を選びなさい。","options":["次ぐ","湿る","担ぐ","付き合う"],"answer":"担ぐ","explanationKo":"「担ぐ」의 핵심 의미는 메다; 추켜세우다; 미신이나 장난에 속이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3392","prompt":"「上から覆うように載せる。また、責任などを他人に負わせる。」という意味に最も近い語を選びなさい。","options":["引き出す","被せる","見送る","釣り合う"],"answer":"被せる","explanationKo":"「被せる」의 핵심 의미는 씌우다; 덮다; 책임을 떠넘기다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3393","prompt":"「植物が水分を失って死ぬ。また、勢いや機能が衰える。」という意味に最も近い語を選びなさい。","options":["枯れる","千切る","関わる","静まる"],"answer":"枯れる","explanationKo":"「枯れる」의 핵심 의미는 시들다; 생기나 기능이 쇠하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3394","prompt":"「水分を取り除いて乾いた状態にする。」という意味に最も近い語を選びなさい。","options":["引き止める","錆びる","遡る","乾かす"],"answer":"乾かす","explanationKo":"「乾かす」의 핵심 의미는 말리다; 수분을 없애다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3395","prompt":"「水分を欲する。また、何かを強く求める。」という意味に最も近い語を選びなさい。","options":["編む","固まる","渇く","悔やむ"],"answer":"渇く","explanationKo":"「渇く」의 핵심 의미는 목마르다; 강하게 갈망하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','grammar',1,'〜にとどまらず','{"pattern":"〜にとどまらず","meaningKo":"〜에 그치지 않고","explanation":"〜にとどまらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"影響は国内にとどまらず、周辺地域にも及んだ。","ko":"문맥에서 〜에 그치지 않고의 의미로 쓰였다."},{"ja":"この技術は医療にとどまらず、教育にも応用されている。","ko":"이 문장도 〜에 그치지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','grammar',2,'〜のみならず','{"pattern":"〜のみならず","meaningKo":"〜뿐만 아니라","explanation":"〜のみならず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"費用のみならず、維持に必要な人員も検討すべきだ。","ko":"문맥에서 〜뿐만 아니라의 의미로 쓰였다."},{"ja":"本人のみならず、家族への支援も必要である。","ko":"이 문장도 〜뿐만 아니라의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n影響は国内（　）、周辺地域にも及んだ。","options":["〜っぱなし","〜に際して","〜をおいて","〜にとどまらず"],"answer":"〜にとどまらず","explanationKo":"문맥상 〜에 그치지 않고를 나타내는 「〜にとどまらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n費用（　）、維持に必要な人員も検討すべきだ。","options":["〜を前提として","〜を踏まえて","〜のみならず","〜に堪えない"],"answer":"〜のみならず","explanationKo":"문맥상 〜뿐만 아니라를 나타내는 「〜のみならず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n使わない設備を保管し続けるのは、放置（　）。","options":["〜に基づいて","〜も同然だ","〜てならない","〜に限ったことではない"],"answer":"〜も同然だ","explanationKo":"문맥상 〜나 다름없다를 나타내는 「〜も同然だ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-12','reading',1,'法則と傾向を区別する','{"passage":"観察結果から規則性を見いだすことには、現象を説明し予測する手掛かりになることという利点がある。しかし、限られた標本の傾向を普遍的な法則と断定することに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、成立条件と反例の有無を繰り返し検証することが重要なのである。","questions":[{"prompt":"「法則と傾向を区別する」について筆者が最も重視していることは何か。","options":["成立条件と反例の有無を繰り返し検証すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"成立条件と反例の有無を繰り返し検証すること","explanationKo":"본문에서는 成立条件と反例の有無を繰り返し検証すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["限られた標本の傾向を普遍的な法則と断定すること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"限られた標本の傾向を普遍的な法則と断定すること","explanationKo":"주의할 점은 限られた標本の傾向を普遍的な法則と断定すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["現象を説明し予測する手掛かりになること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"現象を説明し予測する手掛かりになること","explanationKo":"観察結果から規則性を見いだすこと에는 現象を説明し予測する手掛かりになること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3401","prompt":"「心得る」の読み方として最も適切なものを選びなさい。","options":["つく","こころえる","かかわる","しずまる"],"answer":"こころえる","explanationKo":"「心得る」는 「こころえる」라고 읽는다. 뜻은 알아두다; 이해하다; 맡아 처리하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3402","prompt":"「仕上がる」の読み方として最も適切なものを選びなさい。","options":["しあがる","さびる","さかのぼる","うつ"],"answer":"しあがる","explanationKo":"「仕上がる」는 「しあがる」라고 읽는다. 뜻은 완성되다; 마무리되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3403","prompt":"「背負う」の読み方として最も適切なものを選びなさい。","options":["あむ","かたまる","いいだす","せおう"],"answer":"せおう","explanationKo":"「背負う」는 「せおう」라고 읽는다. 뜻은 등에 지다; 책임이나 부담을 떠맡다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3404","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n制度を利用者の実情に（　）ため、運用を見直した。","options":["絞る","討つ","近付ける","承る"],"answer":"近付ける","explanationKo":"문맥상 「近付ける」가 가장 자연스럽다. 가까이하다; 거리나 상태를 접근시키다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3405","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n危険区域には決して（　）べきではない。","options":["剃る","近寄る","振る舞う","蹴る"],"answer":"近寄る","explanationKo":"문맥상 「近寄る」가 가장 자연스럽다. 가까이 다가가다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3406","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n遠方へ（　）前に、交通情報を確認した。","options":["出掛ける","見舞う","取り消す","突き当たる"],"answer":"出掛ける","explanationKo":"문맥상 「出掛ける」가 가장 자연스럽다. 외출하다; 어떤 목적지로 나가다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3407","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n海外からの訪問団を空港で（　）予定だ。","options":["引き出す","汲む","刷る","出迎える"],"answer":"出迎える","explanationKo":"문맥상 「出迎える」가 가장 자연스럽다. 마중 나가다; 나가서 맞이하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3408","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n交渉が（　）ほど、双方の負担は大きくなる。","options":["縮れる","縛る","長引く","言付ける"],"answer":"長引く","explanationKo":"문맥상 「長引く」가 가장 자연스럽다. 오래 끌다; 예상보다 장기간 계속되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3409","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n短期間だけ（　）商品より、長く使える製品を目指す。","options":["渇く","流行る","遡る","討つ"],"answer":"流行る","explanationKo":"문맥상 「流行る」가 가장 자연스럽다. 유행하다; 질병 등이 널리 퍼지다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3410","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n成功例をそのまま（　）だけでは、同じ成果は得られない。","options":["真似る","待ち合わせる","著す","迫る"],"answer":"真似る","explanationKo":"문맥상 「真似る」가 가장 자연스럽다. 흉내 내다; 본떠 따라 하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3411","prompt":"「去る人を送り出す。また、実施や決定を今回は控える。」という意味に最も近い語を選びなさい。","options":["取り出す","通り掛かる","転がす","見送る"],"answer":"見送る","explanationKo":"「見送る」의 핵심 의미는 배웅하다; 실행이나 결정을 보류하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3412","prompt":"「高い場所から下の方を見る。」という意味に最も近い語を選びなさい。","options":["剃る","兼ねる","見下ろす","蹴る"],"answer":"見下ろす","explanationKo":"「見下ろす」의 핵심 의미는 내려다보다; 높은 곳에서 아래를 보다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3413","prompt":"「もう一度調べて、内容や評価を改める。」という意味に最も近い語を選びなさい。","options":["出迎える","見直す","妥当","通ずる"],"answer":"見直す","explanationKo":"「見直す」의 핵심 의미는 재검토하다; 다시 보고 평가를 바꾸다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3414","prompt":"「何度も見て、珍しく感じなくなる。」という意味に最も近い語を選びなさい。","options":["見慣れる","汲む","刷る","兼ねる"],"answer":"見慣れる","explanationKo":"「見慣れる」의 핵심 의미는 눈에 익다; 자주 보아 익숙해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3415","prompt":"「病人などを訪ねて慰める。また、災害や不幸が人を襲う。」という意味に最も近い語を選びなさい。","options":["縮れる","縛る","映る","見舞う"],"answer":"見舞う","explanationKo":"「見舞う」의 핵심 의미는 문병하다; 재해나 불행이 덮치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','grammar',1,'〜も同然だ','{"pattern":"〜も同然だ","meaningKo":"〜나 다름없다","explanation":"〜も同然だ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"根拠を示さずに結論を出すのは、推測も同然だ。","ko":"문맥에서 〜나 다름없다의 의미로 쓰였다."},{"ja":"使わない設備を保管し続けるのは、放置も同然だ。","ko":"이 문장도 〜나 다름없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','grammar',2,'〜ないものでもない','{"pattern":"〜ないものでもない","meaningKo":"전혀 〜할 수 없는 것은 아니다","explanation":"〜ないものでもない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"条件を見直せば、期限を延長できないものでもない。","ko":"문맥에서 전혀 〜할 수 없는 것은 아니다의 의미로 쓰였다."},{"ja":"十分な根拠があれば、その案に賛成しないものでもない。","ko":"이 문장도 전혀 〜할 수 없는 것은 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠を示さずに結論を出すのは、推測（　）。","options":["〜に限ったことではない","〜に基づいて","〜も同然だ","〜てならない"],"answer":"〜も同然だ","explanationKo":"문맥상 〜나 다름없다를 나타내는 「〜も同然だ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n条件を見直せば、期限を延長でき（　）。","options":["〜に沿って","〜ないものでもない","〜とみえて","〜を問わず"],"answer":"〜ないものでもない","explanationKo":"문맥상 전혀 〜할 수 없는 것은 아니다를 나타내는 「〜ないものでもない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n本人に理由を聞こうとしたが、会え（　）に終わった。","options":["〜ずじまい","〜ものを","〜に限らず","〜に応じて"],"answer":"〜ずじまい","explanationKo":"문맥상 결국 〜하지 못한 채 끝남를 나타내는 「〜ずじまい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-13','reading',1,'膨大な記録から残すものを選ぶ','{"passage":"活動の履歴を将来のために保存することには、過去の判断と変化を検証できることという利点がある。しかし、量が増えすぎると重要な情報を発見しにくくなることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、保存目的と利用期限に応じて情報を選別することが重要なのである。","questions":[{"prompt":"「膨大な記録から残すものを選ぶ」について筆者が最も重視していることは何か。","options":["保存目的と利用期限に応じて情報を選別すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"保存目的と利用期限に応じて情報を選別すること","explanationKo":"본문에서는 保存目的と利用期限に応じて情報を選別すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["量が増えすぎると重要な情報を発見しにくくなること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"量が増えすぎると重要な情報を発見しにくくなること","explanationKo":"주의할 점은 量が増えすぎると重要な情報を発見しにくくなること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["過去の判断と変化を検証できること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"過去の判断と変化を検証できること","explanationKo":"活動の履歴を将来のために保存すること에는 過去の判断と変化を検証できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3421","prompt":"「打ち消す」の読み方として最も適切なものを選びなさい。","options":["でむかえる","よびかける","うちけす","つうずる"],"answer":"うちけす","explanationKo":"「打ち消す」는 「うちけす」라고 읽는다. 뜻은 부정하다; 효과나 영향을 상쇄하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3422","prompt":"「売り切れる」の読み方として最も適切なものを選びなさい。","options":["かえる","うりきれる","する","かねる"],"answer":"うりきれる","explanationKo":"「売り切れる」는 「うりきれる」라고 읽는다. 뜻은 매진되다; 전부 팔리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3423","prompt":"「追い掛ける」の読み方として最も適切なものを選びなさい。","options":["おいかける","うすめる","くみたてる","おさえる"],"answer":"おいかける","explanationKo":"「追い掛ける」는 「おいかける」라고 읽는다. 뜻은 뒤쫓다; 목표나 유행을 계속 좇다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3424","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新興企業が短期間で既存企業を（　）例もある。","options":["渇く","打ち消す","裏返す","追い越す"],"answer":"追い越す","explanationKo":"문맥상 「追い越す」가 가장 자연스럽다. 추월하다; 앞선 대상보다 더 앞서다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3425","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n経験があるから必ず成功すると（　）のは危険だ。","options":["引っ掛かる","刺さる","思い込む","ひっくり返す"],"answer":"思い込む","explanationKo":"문맥상 「思い込む」가 가장 자연스럽다. 굳게 믿다; 근거 없이 단정하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3426","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）案を並べるだけでなく、実現可能性も検討する。","options":["超える","思い付く","転がす","助かる"],"answer":"思い付く","explanationKo":"문맥상 「思い付く」가 가장 자연스럽다. 생각해 내다; 문득 떠오르다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3427","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複数の証拠を基に論理を（　）。","options":["組み立てる","出来上がる","張り切る","捜す"],"answer":"組み立てる","explanationKo":"문맥상 「組み立てる」가 가장 자연스럽다. 조립하다; 논리나 계획을 체계적으로 구성하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3428","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n定員に達した場合は期限前でも募集を（　）。","options":["出迎える","呼び掛ける","敬う","締め切る"],"answer":"締め切る","explanationKo":"문맥상 「締め切る」가 가장 자연스럽다. 마감하다; 신청이나 접수를 끝내다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3429","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n湖の水は底が見えるほど（　）。","options":["揃う","羨む","透き通る","怠る"],"answer":"透き通る","explanationKo":"문맥상 「透き通る」가 가장 자연스럽다. 투명하게 비치다; 맑고 선명하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3430","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n判断に迷ったときは、一度（　）ことも必要だ。","options":["思い付く","立ち止まる","映る","仕上がる"],"answer":"立ち止まる","explanationKo":"문맥상 「立ち止まる」가 가장 자연스럽다. 멈춰 서다; 진행을 잠시 멈추고 생각하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3431","prompt":"「勢いよく中へ入れる。また、深く追及したり鋭く指摘したりする。」という意味に最も近い語を選びなさい。","options":["突っ込む","打ち消す","裏返す","遭う"],"answer":"突っ込む","explanationKo":"「突っ込む」의 핵심 의미는 밀어 넣다; 깊이 파고들다; 날카롭게 지적하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3432","prompt":"「二つのものの程度や価値が均衡している。」という意味に最も近い語を選びなさい。","options":["引っ掛かる","刺さる","発つ","釣り合う"],"answer":"釣り合う","explanationKo":"「釣り合う」의 핵심 의미는 균형이 맞다; 서로 어울리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3433","prompt":"「液体などの中に混ざる。また、集団や環境になじむ。」という意味に最も近い語を選びなさい。","options":["超える","納める","溶け込む","助かる"],"answer":"溶け込む","explanationKo":"「溶け込む」의 핵심 의미는 녹아들다; 집단이나 환경에 자연스럽게 섞이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3434","prompt":"「勢いよく中へ入る。また、新しい分野などへ思い切って入る。」という意味に最も近い語を選びなさい。","options":["暖める","飛び込む","浮かべる","売り切れる"],"answer":"飛び込む","explanationKo":"「飛び込む」의 핵심 의미는 뛰어들다; 갑자기 안으로 들어가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3435","prompt":"「外にあるものや考え方を受け入れて活用する。」という意味に最も近い語を選びなさい。","options":["取り入れる","焚く","超える","枯れる"],"answer":"取り入れる","explanationKo":"「取り入れる」의 핵심 의미는 받아들이다; 도입하다; 안으로 들이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','grammar',1,'〜ずじまい','{"pattern":"〜ずじまい","meaningKo":"결국 〜하지 못한 채 끝남","explanation":"〜ずじまい는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"忙しさに追われ、資料を確認できずじまいだった。","ko":"문맥에서 결국 〜하지 못한 채 끝남의 의미로 쓰였다."},{"ja":"本人に理由を聞こうとしたが、会えずじまいに終わった。","ko":"이 문장도 결국 〜하지 못한 채 끝남의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','grammar',2,'〜っぱなし','{"pattern":"〜っぱなし","meaningKo":"계속 〜한 채","explanation":"〜っぱなし는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"装置を動かしっぱなしにすると、部品の劣化が早まる。","ko":"문맥에서 계속 〜한 채의 의미로 쓰였다."},{"ja":"窓を開けっぱなしにしたため、資料が雨でぬれた。","ko":"이 문장도 계속 〜한 채의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n忙しさに追われ、資料を確認でき（　）だった。","options":["〜に応じて","〜ずじまい","〜ものを","〜に限らず"],"answer":"〜ずじまい","explanationKo":"문맥상 결국 〜하지 못한 채 끝남를 나타내는 「〜ずじまい」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n装置を動かし（　）にすると、部品の劣化が早まる。","options":["〜っぱなし","〜にあたって","〜ならいざ知らず","〜に伴って"],"answer":"〜っぱなし","explanationKo":"문맥상 계속 〜한 채를 나타내는 「〜っぱなし」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の支援に対し、感謝（　）。","options":["〜に際して","〜とあっては","〜にかかわる","〜に堪えない"],"answer":"〜に堪えない","explanationKo":"문맥상 〜을 견딜 수 없다; 매우 〜하다를 나타내는 「〜に堪えない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-14','reading',1,'民間と公共の役割を分ける','{"passage":"公共サービスに民間の力を活用することには、専門性と機動力を取り入れられることという利点がある。しかし、採算だけでは必要な人にサービスが届かないことに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、公共性を守る条件と責任の所在を契約で定めることが重要なのである。","questions":[{"prompt":"「民間と公共の役割を分ける」について筆者が最も重視していることは何か。","options":["公共性を守る条件と責任の所在を契約で定めること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"公共性を守る条件と責任の所在を契約で定めること","explanationKo":"본문에서는 公共性を守る条件と責任の所在を契約で定めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["採算だけでは必要な人にサービスが届かないこと","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"採算だけでは必要な人にサービスが届かないこと","explanationKo":"주의할 점은 採算だけでは必要な人にサービスが届かないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["専門性と機動力を取り入れられること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"専門性と機動力を取り入れられること","explanationKo":"公共サービスに民間の力を活用すること에는 専門性と機動力を取り入れられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3441","prompt":"「出来上がる」の読み方として最も適切なものを選びなさい。","options":["こえる","おさめる","とりいれる","できあがる"],"answer":"できあがる","explanationKo":"「出来上がる」는 「できあがる」라고 읽는다. 뜻은 완성되다; 다 만들어지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3442","prompt":"「ひっくり返す」の読み方として最も適切なものを選びなさい。","options":["あたためる","くずす","ひっくりかえす","うりきれる"],"answer":"ひっくりかえす","explanationKo":"「ひっくり返す」는 「ひっくりかえす」라고 읽는다. 뜻은 뒤집다; 전복시키다; 결과를 뒤바꾸다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3443","prompt":"「ひっくり返る」の読み方として最も適切なものを選びなさい。","options":["おろす","ひっくりかえる","うやまう","ちぢむ"],"answer":"ひっくりかえる","explanationKo":"「ひっくり返る」는 「ひっくりかえる」라고 읽는다. 뜻은 뒤집히다; 전복되다; 상황이 역전되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3444","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n役職が上だからといって（　）人は信頼されない。","options":["威張る","羨む","長引く","立ち止まる"],"answer":"威張る","explanationKo":"문맥상 「威張る」가 가장 자연스럽다. 뽐내다; 거드름 피우다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3445","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n資料を（　）と、裏面に注意事項が記載されている。","options":["思い付く","区切る","教わる","裏返す"],"answer":"裏返す","explanationKo":"문맥상 「裏返す」가 가장 자연스럽다. 뒤집다; 안팎을 바꾸다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3446","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n市場が（　）までは慎重な判断が求められる。","options":["射す","散らかす","落ち着く","遭う"],"answer":"落ち着く","explanationKo":"문맥상 「落ち着く」가 가장 자연스럽다. 진정되다; 안정되다; 정착하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3447","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの案件が（　）まで、新しい仕事には着手できない。","options":["被せる","片付く","発つ","接する"],"answer":"片付く","explanationKo":"문맥상 「片付く」가 가장 자연스럽다. 정리되다; 해결되다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3448","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n複雑な仕組みを身近な道具に（　）と理解しやすい。","options":["例える","呼び出す","挿す","足る"],"answer":"例える","explanationKo":"문맥상 「例える」가 가장 자연스럽다. 비유하다; 예를 들어 설명하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3449","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長い説明を項目ごとに（　）と理解しやすい。","options":["暖める","崩す","甘やかす","区切る"],"answer":"区切る","explanationKo":"문맥상 「区切る」가 가장 자연스럽다. 구분하다; 단락 짓다; 일단락하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3450","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n受付の順番が来るまで、こちらに（　）よう案内された。","options":["言付ける","縮れる","腰掛ける","枯れる"],"answer":"腰掛ける","explanationKo":"문맥상 「腰掛ける」가 가장 자연스럽다. 걸터앉다; 앉다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3451","prompt":"「人を介して伝言や品物を相手に届けてもらう。」という意味に最も近い語を選びなさい。","options":["甘やかす","言付ける","錆びる","請う"],"answer":"言付ける","explanationKo":"「言付ける」의 핵심 의미는 전언을 부탁하다; 물건을 맡겨 전하게 하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3452","prompt":"「手で細かく切ったり、一部を引き離したりする。」という意味に最も近い語を選びなさい。","options":["千切る","片付く","教わる","茂る"],"answer":"千切る","explanationKo":"「千切る」의 핵심 의미는 잘게 뜯다; 떼어 내다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3453","prompt":"「人と交際する。また、相手の行動に合わせて一緒に行う。」という意味に最も近い語を選びなさい。","options":["射す","散らかす","逸れる","付き合う"],"answer":"付き合う","explanationKo":"「付き合う」의 핵심 의미는 교제하다; 상대해 주다; 함께하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3454","prompt":"「仕事や責任を自分が受け持つ。」という意味に最も近い語を選びなさい。","options":["暖まる","敷く","引き受ける","片付く"],"answer":"引き受ける","explanationKo":"「引き受ける」의 핵심 의미는 맡다; 인수하다; 책임지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3455","prompt":"「進んできた道を逆に戻る。」という意味に最も近い語を選びなさい。","options":["削る","引き返す","取り入れる","揚げる"],"answer":"引き返す","explanationKo":"「引き返す」의 핵심 의미는 되돌아가다; 되돌리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','grammar',1,'〜に堪えない','{"pattern":"〜に堪えない","meaningKo":"〜을 견딜 수 없다; 매우 〜하다","explanation":"〜に堪えない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事実を軽視する発言は、聞くに堪えない。","ko":"문맥에서 〜을 견딜 수 없다; 매우 〜하다의 의미로 쓰였다."},{"ja":"長年の支援に対し、感謝に堪えない。","ko":"이 문장도 〜을 견딜 수 없다; 매우 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','grammar',2,'〜てならない','{"pattern":"〜てならない","meaningKo":"몹시 〜하다; 〜해서 견딜 수 없다","explanation":"〜てならない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"判断を急ぎすぎたのではないかと、悔やまれてならない。","ko":"문맥에서 몹시 〜하다; 〜해서 견딜 수 없다의 의미로 쓰였다."},{"ja":"被災地の今後が心配でならない。","ko":"이 문장도 몹시 〜하다; 〜해서 견딜 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事実を軽視する発言は、聞く（　）。","options":["〜に堪えない","〜に際して","〜とあっては","〜にかかわる"],"answer":"〜に堪えない","explanationKo":"문맥상 〜을 견딜 수 없다; 매우 〜하다를 나타내는 「〜に堪えない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n判断を急ぎすぎたのではないかと、悔やまれ（　）。","options":["〜を前提として","〜をもって","〜をめぐって","〜てならない"],"answer":"〜てならない","explanationKo":"문맥상 몹시 〜하다; 〜해서 견딜 수 없다를 나타내는 「〜てならない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n説明が難しかった（　）、同じ質問が相次いだ。","options":["〜をおいて","〜を通じて","〜とみえて","〜に限ったことではない"],"answer":"〜とみえて","explanationKo":"문맥상 〜인 듯하여를 나타내는 「〜とみえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-15','reading',1,'目安を絶対条件にしない','{"passage":"判断を助けるおおよその基準を設けることには、初めての人でも行動を選びやすくなることという利点がある。しかし、目安を一律に適用すると個別事情を無視することに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、基準から外れる場合の確認方法も用意することが重要なのである。","questions":[{"prompt":"「目安を絶対条件にしない」について筆者が最も重視していることは何か。","options":["基準から外れる場合の確認方法も用意すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"基準から外れる場合の確認方法も用意すること","explanationKo":"본문에서는 基準から外れる場合の確認方法も用意すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["目安を一律に適用すると個別事情を無視すること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"目安を一律に適用すると個別事情を無視すること","explanationKo":"주의할 점은 目安を一律に適用すると個別事情を無視すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["初めての人でも行動を選びやすくなること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"初めての人でも行動を選びやすくなること","explanationKo":"判断を助けるおおよその基準を設けること에는 初めての人でも行動を選びやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3461","prompt":"「気を付ける」の読み方として最も適切なものを選びなさい。","options":["きをつける","たちどまる","つきあう","つぐ"],"answer":"きをつける","explanationKo":"「気を付ける」는 「きをつける」라고 읽는다. 뜻은 조심하다; 주의하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3462","prompt":"「突き当たる」の読み方として最も適切なものを選びなさい。","options":["かぶせる","たとえる","さめる","つきあたる"],"answer":"つきあたる","explanationKo":"「突き当たる」는 「つきあたる」라고 읽는다. 뜻은 맞부딪치다; 막다른 곳에 이르다; 난관에 봉착하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3463","prompt":"「通り掛かる」の読み方として最も適切なものを選びなさい。","options":["けずる","いやがる","とおりかかる","あげる"],"answer":"とおりかかる","explanationKo":"「通り掛かる」는 「とおりかかる」라고 읽는다. 뜻은 마침 지나가다; 지나가던 길이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3464","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n保険料を指定された口座へ（　）。","options":["目指す","払い込む","甘やかす","嗅ぐ"],"answer":"払い込む","explanationKo":"문맥상 「払い込む」가 가장 자연스럽다. 납입하다; 송금하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3465","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n初日から（　）のはよいが、無理は禁物だ。","options":["張り切る","見下ろす","溶け込む","振る舞う"],"answer":"張り切る","explanationKo":"문맥상 「張り切る」가 가장 자연스럽다. 의욕이 넘치다; 힘을 내다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3466","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明の一部がどうしても（　）ので、再確認した。","options":["付き合う","配る","澄む","引っ掛かる"],"answer":"引っ掛かる","explanationKo":"문맥상 「引っ掛かる」가 가장 자연스럽다. 걸리다; 속다; 마음에 걸리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3467","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n反対意見が出たからといって、すぐに（　）必要はない。","options":["散る","蓄える","引っ込む","茂る"],"answer":"引っ込む","explanationKo":"문맥상 「引っ込む」가 가장 자연스럽다. 들어가다; 물러나다; 움푹 들어가다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3468","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅の改札前で同僚と（　）。","options":["湿る","待ち合わせる","付き合う","次ぐ"],"answer":"待ち合わせる","explanationKo":"문맥상 「待ち合わせる」가 가장 자연스럽다. 약속하여 만나다; 만나기로 하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3469","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n自治体は住民に節電への協力を（　）。","options":["呼び掛ける","敷く","散らす","飢える"],"answer":"呼び掛ける","explanationKo":"문맥상 「呼び掛ける」가 가장 자연스럽다. 부르다; 호소하다; 참여를 촉구하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3470","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n必要に応じて担当者を会議室へ（　）。","options":["削る","嫌がる","担ぐ","呼び出す"],"answer":"呼び出す","explanationKo":"문맥상 「呼び出す」가 가장 자연스럽다. 불러내다; 호출하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3471","prompt":"「災難や事故など、好ましくない出来事を経験する。」という意味に最も近い語を選びなさい。","options":["目指す","取り出す","遭う","嗅ぐ"],"answer":"遭う","explanationKo":"「遭う」의 핵심 의미는 (재난·사고 등을) 당하다; 맞닥뜨리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3472","prompt":"「うちわなどを動かして風を起こす。」という意味に最も近い語を選びなさい。","options":["越す","扇ぐ","溶け込む","振る舞う"],"answer":"扇ぐ","explanationKo":"「扇ぐ」의 핵심 의미는 부채질하다; 바람을 일으키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3473","prompt":"「高く上げる。また、例や理由を示したり、成果を生み出したりする。」という意味に最も近い語を選びなさい。","options":["挙げる","嗅ぐ","目指す","取り出す"],"answer":"挙げる","explanationKo":"「挙げる」의 핵심 의미는 들다; 제시하다; 성과를 올리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3474","prompt":"「理想とする人や物事に強く心を引かれる。」という意味に最も近い語を選びなさい。","options":["溶け込む","振る舞う","蹴る","憧れる"],"answer":"憧れる","explanationKo":"「憧れる」의 핵심 의미는 동경하다; 선망하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3475","prompt":"「温度が上がり、暖かい状態になる。」という意味に最も近い語を選びなさい。","options":["引き受ける","承る","暖まる","凍える"],"answer":"暖まる","explanationKo":"「暖まる」의 핵심 의미는 따뜻해지다; 몸이 데워지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','grammar',1,'〜とみえて','{"pattern":"〜とみえて","meaningKo":"〜인 듯하여","explanation":"〜とみえて는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"道路が混雑しているとみえて、配送が大幅に遅れている。","ko":"문맥에서 〜인 듯하여의 의미로 쓰였다."},{"ja":"説明が難しかったとみえて、同じ質問が相次いだ。","ko":"이 문장도 〜인 듯하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','grammar',2,'〜ものを','{"pattern":"〜ものを","meaningKo":"〜했을 텐데; 그런데도","explanation":"〜ものを는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"早く相談すれば対応できたものを、一人で抱え込んでしまった。","ko":"문맥에서 〜했을 텐데; 그런데도의 의미로 쓰였다."},{"ja":"確認しておけば防げたものを、手順を省いてしまった。","ko":"이 문장도 〜했을 텐데; 그런데도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n道路が混雑している（　）、配送が大幅に遅れている。","options":["〜に限ったことではない","〜をおいて","〜を通じて","〜とみえて"],"answer":"〜とみえて","explanationKo":"문맥상 〜인 듯하여를 나타내는 「〜とみえて」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n早く相談すれば対応できた（　）、一人で抱え込んでしまった。","options":["〜を踏まえて","〜にとどまらず","〜ものを","〜を問わず"],"answer":"〜ものを","explanationKo":"문맥상 〜했을 텐데; 그런데도를 나타내는 「〜ものを」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n調査を始める（　）、目的と方法を共有した。","options":["〜のみならず","〜にあたって","〜に限らず","〜に基づいて"],"answer":"〜にあたって","explanationKo":"문맥상 〜에 즈음하여; 〜할 때를 나타내는 「〜にあたって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-16','reading',1,'専門用語を文脈で説明する','{"passage":"分野固有の用語を使って情報を伝えることには、複雑な内容を正確かつ簡潔に共有できることという利点がある。しかし、定義だけでは実際の適用範囲が伝わらないことに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、具体例と反例を添えて文脈の中で示すことが重要なのである。","questions":[{"prompt":"「専門用語を文脈で説明する」について筆者が最も重視していることは何か。","options":["具体例と反例を添えて文脈の中で示すこと","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"具体例と反例を添えて文脈の中で示すこと","explanationKo":"본문에서는 具体例と反例を添えて文脈の中で示すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["定義だけでは実際の適用範囲が伝わらないこと","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"定義だけでは実際の適用範囲が伝わらないこと","explanationKo":"주의할 점은 定義だけでは実際の適用範囲が伝わらないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["複雑な内容を正確かつ簡潔に共有できること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"複雑な内容を正確かつ簡潔に共有できること","explanationKo":"分野固有の用語を使って情報を伝えること에는 複雑な内容を正確かつ簡潔に共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3481","prompt":"「揚げる」の読み方として最も適切なものを選びなさい。","options":["とおりかかる","あげる","めざす","とりだす"],"answer":"あげる","explanationKo":"「揚げる」는 「あげる」라고 읽는다. 뜻은 튀기다; 높이 올리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3482","prompt":"「次ぐ」の読み方として最も適切なものを選びなさい。","options":["つぐ","たくわえる","ちかづける","きをつける"],"answer":"つぐ","explanationKo":"「次ぐ」는 「つぐ」라고 읽는다. 뜻은 뒤를 잇다; 다음가다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3483","prompt":"「配る」の読み方として最も適切なものを選びなさい。","options":["ひきうける","うけたまわる","しぼる","くばる"],"answer":"くばる","explanationKo":"「配る」는 「くばる」라고 읽는다. 뜻은 나누어 주다; 배부하다; 신경을 쓰다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3484","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n現場の事情を（　）柔軟な対応が求められる。","options":["映す","焦がす","汲む","探る"],"answer":"汲む","explanationKo":"문맥상 「汲む」가 가장 자연스럽다. 물을 긷다; 사정을 헤아리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3485","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n会社側が組合の要求を一方的に（　）ことは避けるべきだ。","options":["ひっくり返す","蹴る","担ぐ","言い出す"],"answer":"蹴る","explanationKo":"문맥상 「蹴る」가 가장 자연스럽다. 차다; 제안 등을 거절하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3486","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n予算が百万円を（　）場合は追加の承認が必要だ。","options":["越す","取り出す","通り掛かる","転がる"],"answer":"越す","explanationKo":"문맥상 「越す」가 가장 자연스럽다. 넘다; 건너다; 이사하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3487","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n汚れを落とそうとして強く（　）と、表面が傷つく。","options":["蹴る","炊く","崩れる","擦る"],"answer":"擦る","explanationKo":"문맥상 「擦る」가 가장 자연스럽다. 문지르다; 비비다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3488","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n説明を聞いた参加者から安堵の笑みが（　）。","options":["通り掛かる","転がす","零れる","取り出す"],"answer":"零れる","explanationKo":"문맥상 「零れる」가 가장 자연스럽다. 쏟아지다; 넘쳐흐르다; 무심코 새어 나오다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3489","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n重い荷物は台車に載せて（　）ほうが安全だ。","options":["著す","転がす","近付ける","気を付ける"],"answer":"転がす","explanationKo":"문맥상 「転がす」가 가장 자연스럽다. 굴리다; 넘어뜨리다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3490","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n固定しないと容器が床を（　）恐れがある。","options":["転がる","承る","絞る","占う"],"answer":"転がる","explanationKo":"문맥상 「転がる」가 가장 자연스럽다. 구르다; 나뒹굴다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3491","prompt":"「見失った人や物の所在を調べ求める。」という意味に最も近い語を選びなさい。","options":["映す","焦がす","追い越す","捜す"],"answer":"捜す","explanationKo":"「捜す」의 핵심 의미는 수색하다; 잃어버린 것을 찾다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3492","prompt":"「先の鋭い物が中に入り込む。また、言葉などが強く心に残る。」という意味に最も近い語を選びなさい。","options":["ひっくり返す","引っ掛かる","刺さる","言い出す"],"answer":"刺さる","explanationKo":"「刺さる」의 핵심 의미는 박히다; 찔리다; 마음에 강하게 와닿다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3493","prompt":"「先の鋭い物を突き入れる。また、虫が針などで攻撃する。」という意味に最も近い語を選びなさい。","options":["畳む","刺す","通り掛かる","転がす"],"answer":"刺す","explanationKo":"「刺す」의 핵심 의미는 찌르다; 쏘다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3494","prompt":"「細長い物を中へ入れたり、花などを器に入れたりする。」という意味に最も近い語を選びなさい。","options":["挿す","炊く","崩れる","薄める"],"answer":"挿す","explanationKo":"「挿す」의 핵심 의미는 꽂다; 끼워 넣다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3495","prompt":"「光が一定の方向から入り込む。」という意味に最も近い語を選びなさい。","options":["暴れる","真似る","挙げる","射す"],"answer":"射す","explanationKo":"「射す」의 핵심 의미는 빛이 비치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','grammar',1,'〜にあたって','{"pattern":"〜にあたって","meaningKo":"〜에 즈음하여; 〜할 때","explanation":"〜にあたって는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"制度を導入するにあたって、影響を受ける人に説明した。","ko":"문맥에서 〜에 즈음하여; 〜할 때의 의미로 쓰였다."},{"ja":"調査を始めるにあたって、目的と方法を共有した。","ko":"이 문장도 〜에 즈음하여; 〜할 때의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','grammar',2,'〜に際して','{"pattern":"〜に際して","meaningKo":"〜할 때; 〜에 즈음하여","explanation":"〜に際して는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"契約の更新に際して、条件を改めて確認した。","ko":"문맥에서 〜할 때; 〜에 즈음하여의 의미로 쓰였다."},{"ja":"機器の使用に際して、安全上の注意を説明した。","ko":"이 문장도 〜할 때; 〜에 즈음하여의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n制度を導入する（　）、影響を受ける人に説明した。","options":["〜に基づいて","〜のみならず","〜にあたって","〜に限らず"],"answer":"〜にあたって","explanationKo":"문맥상 〜에 즈음하여; 〜할 때를 나타내는 「〜にあたって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n契約の更新（　）、条件を改めて確認した。","options":["〜も同然だ","〜に際して","〜ならいざ知らず","〜に沿って"],"answer":"〜に際して","explanationKo":"문맥상 〜할 때; 〜에 즈음하여를 나타내는 「〜に際して」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n情報を公開すること（　）、記録を整理した。","options":["〜を前提として","〜とあっては","〜に応じて","〜ないものでもない"],"answer":"〜を前提として","explanationKo":"문맥상 〜을 전제로를 나타내는 「〜を前提として」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-17','reading',1,'要旨に残すべき情報','{"passage":"長い報告を短くまとめることには、読み手が結論と根拠を素早く把握できることという利点がある。しかし、短さを優先すると重要な条件や不確実性が消えることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、結論と主要根拠と適用条件を残すことが重要なのである。","questions":[{"prompt":"「要旨に残すべき情報」について筆者が最も重視していることは何か。","options":["結論と主要根拠と適用条件を残すこと","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"結論と主要根拠と適用条件を残すこと","explanationKo":"본문에서는 結論と主要根拠と適用条件を残すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["短さを優先すると重要な条件や不確実性が消えること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"短さを優先すると重要な条件や不確実性が消えること","explanationKo":"주의할 점은 短さを優先すると重要な条件や不確実性が消えること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["読み手が結論と根拠を素早く把握できること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"読み手が結論と根拠を素早く把握できること","explanationKo":"長い報告を短くまとめること에는 読み手が結論と根拠を素早く把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3501","prompt":"「静まる」の読み方として最も適切なものを選びなさい。","options":["たたむ","さまたげる","しずまる","ころがす"],"answer":"しずまる","explanationKo":"「静まる」는 「しずまる」라고 읽는다. 뜻은 조용해지다; 진정되다; 가라앉다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3502","prompt":"「湿る」の読み方として最も適切なものを選びなさい。","options":["おいかける","しめる","くずれる","うすめる"],"answer":"しめる","explanationKo":"「湿る」는 「しめる」라고 읽는다. 뜻은 축축해지다; 습기를 띠다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3503","prompt":"「澄む」の読み方として最も適切なものを選びなさい。","options":["すむ","まねる","あげる","かたむく"],"answer":"すむ","explanationKo":"「澄む」는 「すむ」라고 읽는다. 뜻은 맑아지다; 투명해지다; 소리가 청명하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3504","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n修正内容を確認してから資料を（　）。","options":["著す","耕す","拝む","刷る"],"answer":"刷る","explanationKo":"문맥상 「刷る」가 가장 자연스럽다. 인쇄하다; 찍어 내다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3505","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n肌を傷つけないよう、慎重にひげを（　）。","options":["背負う","締め切る","剃る","占う"],"answer":"剃る","explanationKo":"문맥상 「剃る」가 가장 자연스럽다. (털을) 깎다; 면도하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3506","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n災害訓練では屋外で大量の米を（　）。","options":["遭う","炊く","追い越す","裏返す"],"answer":"炊く","explanationKo":"문맥상 「炊く」가 가장 자연스럽다. 밥을 짓다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3507","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n乾燥した場所で火を（　）際は十分な注意が必要だ。","options":["焚く","引っ掛かる","刺さる","溜まる"],"answer":"焚く","explanationKo":"문맥상 「焚く」가 가장 자연스럽다. 불을 피우다; 연료를 태우다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3508","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n資料を事前に共有してもらえると非常に（　）。","options":["畳む","妨げる","代える","助かる"],"answer":"助かる","explanationKo":"문맥상 「助かる」가 가장 자연스럽다. 살아나다; 도움을 받다; 수고를 덜다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3509","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長年続けた店を（　）決断は容易ではない。","options":["追い掛ける","応じる","畳む","薄める"],"answer":"畳む","explanationKo":"문맥상 「畳む」가 가장 자연스럽다. 개다; 접다; 사업을 정리하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3510","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅前に新しい公共施設が（　）予定だ。","options":["味わう","建つ","挙げる","傾く"],"answer":"建つ","explanationKo":"문맥상 「建つ」가 가장 자연스럽다. 세워지다; 건물이 들어서다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3511","prompt":"「目的地に向かって、その場所を出発する。」という意味に最も近い語を選びなさい。","options":["発つ","耕す","拝む","流行る"],"answer":"発つ","explanationKo":"「発つ」의 핵심 의미는 출발하다; 떠나다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3512","prompt":"「物や仕事などが少しずつ増えて一か所に集まる。」という意味に最も近い語を選びなさい。","options":["背負う","締め切る","区切る","溜まる"],"answer":"溜まる","explanationKo":"「溜まる」의 핵심 의미는 쌓이다; 모이다; 밀리다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3513","prompt":"「物や金銭などを少しずつ集めて蓄える。」という意味に最も近い語を選びなさい。","options":["拝む","流行る","溜める","誓う"],"answer":"溜める","explanationKo":"「溜める」의 핵심 의미는 모으다; 저축하다; 쌓아 두다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3514","prompt":"「必要な量や条件を満たしている。」という意味に最も近い語を選びなさい。","options":["攻める","足る","刺さる","発つ"],"answer":"足る","explanationKo":"「足る」의 핵심 의미는 충분하다; 족하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3515","prompt":"「しわが寄ったり、細かく曲がった状態になったりする。」という意味に最も近い語を選びなさい。","options":["縮れる","裏返す","遭う","射す"],"answer":"縮れる","explanationKo":"「縮れる」의 핵심 의미는 곱슬거리다; 오그라들다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','grammar',1,'〜を前提として','{"pattern":"〜を前提として","meaningKo":"〜을 전제로","explanation":"〜を前提として는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"長期的な利用を前提として、維持費も計算に入れた。","ko":"문맥에서 〜을 전제로의 의미로 쓰였다."},{"ja":"情報を公開することを前提として、記録を整理した。","ko":"이 문장도 〜을 전제로의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','grammar',2,'〜に限ったことではない','{"pattern":"〜に限ったことではない","meaningKo":"〜에만 한정된 일이 아니다","explanation":"〜に限ったことではない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"人手不足は、この業界に限ったことではない。","ko":"문맥에서 〜에만 한정된 일이 아니다의 의미로 쓰였다."},{"ja":"情報管理の課題は、大企業に限ったことではない。","ko":"이 문장도 〜에만 한정된 일이 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長期的な利用（　）、維持費も計算に入れた。","options":["〜ないものでもない","〜を前提として","〜とあっては","〜に応じて"],"answer":"〜を前提として","explanationKo":"문맥상 〜을 전제로를 나타내는 「〜を前提として」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n人手不足は、この業界（　）。","options":["〜に限ったことではない","〜をもって","〜に伴って","〜ずじまい"],"answer":"〜に限ったことではない","explanationKo":"문맥상 〜에만 한정된 일이 아니다를 나타내는 「〜に限ったことではない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n昼夜（　）、緊急の相談を受け付けている。","options":["〜をおいて","〜にかかわる","〜っぱなし","〜を問わず"],"answer":"〜を問わず","explanationKo":"문맥상 〜을 불문하고를 나타내는 「〜を問わず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-18','reading',1,'予備を持つだけでは足りない','{"passage":"障害に備えて代替手段を準備することには、主要な手段が使えない時も活動を続けられることという利点がある。しかし、保管するだけで試さなければ必要時に動かないことに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、定期的に切替手順と実際の動作を確認することが重要なのである。","questions":[{"prompt":"「予備を持つだけでは足りない」について筆者が最も重視していることは何か。","options":["定期的に切替手順と実際の動作を確認すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"定期的に切替手順と実際の動作を確認すること","explanationKo":"본문에서는 定期的に切替手順と実際の動作を確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["保管するだけで試さなければ必要時に動かないこと","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"保管するだけで試さなければ必要時に動かないこと","explanationKo":"주의할 점은 保管するだけで試さなければ必要時に動かないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["主要な手段が使えない時も活動を続けられること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"主要な手段が使えない時も活動を続けられること","explanationKo":"障害に備えて代替手段を準備すること에는 主要な手段が使えない時も活動を続けられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3521","prompt":"「分類」の読み方として最も適切なものを選びなさい。","options":["ほうそく","りんじ","せいぞん","ぶんるい"],"answer":"ぶんるい","explanationKo":"「分類」는 「ぶんるい」라고 읽는다. 뜻은 분류; 공통된 성질에 따라 종류를 나눔이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3522","prompt":"「並行」の読み方として最も適切なものを選びなさい。","options":["ぶんぷ","せいとう","へいこう","しんだん"],"answer":"へいこう","explanationKo":"「並行」는 「へいこう」라고 읽는다. 뜻은 병행; 둘 이상의 일을 동시에 나란히 진행함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3523","prompt":"「編集」の読み方として最も適切なものを選びなさい。","options":["ぶんげい","へんしゅう","しりょう","みまん"],"answer":"へんしゅう","explanationKo":"「編集」는 「へんしゅう」라고 읽는다. 뜻은 편집; 자료를 모아 구성하고 다듬음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3524","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故の再発（　）には原因の共有と手順の改善が欠かせない。","options":["防止","例外","整備","募集"],"answer":"防止","explanationKo":"문맥상 「防止」가 가장 자연스럽다. 방지; 좋지 않은 일이 생기지 않도록 막음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3525","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n調査結果を踏まえて、組織の運営（　）を改めた。","options":["迷信","標本","増大","方針"],"answer":"方針","explanationKo":"문맥상 「方針」가 가장 자연스럽다. 방침; 일을 처리하거나 나아갈 기본 방향라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3526","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n限られた事例だけで普遍的な（　）を導くのは危険だ。","options":["輸送","段階","法則","宣伝"],"answer":"法則","explanationKo":"문맥상 「法則」가 가장 자연스럽다. 법칙; 일정한 조건에서 성립하는 규칙적인 관계라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3527","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な記録から必要な情報だけを抽出する仕組みを整えた。","options":["縛る","膨大","測定","敬う"],"answer":"膨大","explanationKo":"문맥상 「膨大」가 가장 자연스럽다. 방대함; 규모나 수량이 매우 큼라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3528","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n地域の（　）を強化するため、夜間の巡回を増やした。","options":["防犯","超過","測定","体系"],"answer":"防犯","explanationKo":"문맥상 「防犯」가 가장 자연스럽다. 방범; 범죄를 미리 막음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3529","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n市は新しい計画に対する住民の意見を（　）している。","options":["文体","相違","普及","募集"],"answer":"募集","explanationKo":"문맥상 「募集」가 가장 자연스럽다. 모집; 널리 알려 사람이나 작품 등을 모음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3530","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの制度は（　）、支援を受けにくい人を守るために設けられた。","options":["受け持つ","取り出す","本来","背負う"],"answer":"本来","explanationKo":"문맥상 「本来」가 가장 자연스럽다. 본래; 원래부터 그러함; 마땅히 그래야 함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3531","prompt":"「接触する物体の運動を妨げる力。また、人や集団の間の対立。」という意味に最も近い語を選びなさい。","options":["防犯","摩擦","対立","素質"],"answer":"摩擦","explanationKo":"「摩擦」의 핵심 의미는 마찰; 맞닿은 물체의 운동을 방해하는 힘; 사람 사이의 충돌이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3532","prompt":"「社会や法律の上で個人が占める地位や立場。」という意味に最も近い語を選びなさい。","options":["身分","利害","臨時","生存"],"answer":"身分","explanationKo":"「身分」의 핵심 의미는 신분; 사회나 법률상 차지하는 지위이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3533","prompt":"「ある数値や程度に達していないこと。」という意味に最も近い語を選びなさい。","options":["募集","流域","消化","未満"],"answer":"未満","explanationKo":"「未満」의 핵심 의미는 미만; 정해진 수나 정도에 이르지 않음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3534","prompt":"「政府や公的機関に属さない、一般の社会や企業の領域。」という意味に最も近い語を選びなさい。","options":["摩擦","文芸","民間","標準"],"answer":"民間","explanationKo":"「民間」의 핵심 의미는 민간; 정부 기관이 아닌 일반 사회나 사기업 영역이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3535","prompt":"「数量や範囲に限りがないこと。」という意味に最も近い語を選びなさい。","options":["防止","無限","例外","整備"],"answer":"無限","explanationKo":"「無限」의 핵심 의미는 무한; 한계가 없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','grammar',1,'〜を問わず','{"pattern":"〜を問わず","meaningKo":"〜을 불문하고","explanation":"〜を問わず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"経験の有無を問わず、研修には全員が参加できる。","ko":"문맥에서 〜을 불문하고의 의미로 쓰였다."},{"ja":"昼夜を問わず、緊急の相談を受け付けている。","ko":"이 문장도 〜을 불문하고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','grammar',2,'〜に限らず','{"pattern":"〜に限らず","meaningKo":"〜에 한하지 않고","explanation":"〜に限らず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"都市部に限らず、地方でも同じ問題が起きている。","ko":"문맥에서 〜에 한하지 않고의 의미로 쓰였다."},{"ja":"若者に限らず、幅広い世代がこの制度を利用している。","ko":"이 문장도 〜에 한하지 않고의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n経験の有無（　）、研修には全員が参加できる。","options":["〜を問わず","〜をおいて","〜にかかわる","〜っぱなし"],"answer":"〜を問わず","explanationKo":"문맥상 〜을 불문하고를 나타내는 「〜を問わず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n都市部（　）、地方でも同じ問題が起きている。","options":["〜を踏まえて","〜をめぐって","〜に堪えない","〜に限らず"],"answer":"〜に限らず","explanationKo":"문맥상 〜에 한하지 않고를 나타내는 「〜に限らず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一度（　）、同じ誤りを繰り返すのは問題だ。","options":["〜を通じて","〜てならない","〜ならいざ知らず","〜に基づいて"],"answer":"〜ならいざ知らず","explanationKo":"문맥상 〜라면 몰라도를 나타내는 「〜ならいざ知らず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-19','reading',1,'流域全体で水害を考える','{"passage":"河川の氾濫に備えて地域ごとに対策することには、身近な危険に合わせた避難計画を作れることという利点がある。しかし、行政区域だけで考えると上流と下流の影響を見落とすことに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、水の流れと土地利用を流域全体で捉えることが重要なのである。","questions":[{"prompt":"「流域全体で水害を考える」について筆者が最も重視していることは何か。","options":["水の流れと土地利用を流域全体で捉えること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"水の流れと土地利用を流域全体で捉えること","explanationKo":"본문에서는 水の流れと土地利用を流域全体で捉えること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["行政区域だけで考えると上流と下流の影響を見落とすこと","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"行政区域だけで考えると上流と下流の影響を見落とすこと","explanationKo":"주의할 점은 行政区域だけで考えると上流と下流の影響を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["身近な危険に合わせた避難計画を作れること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"身近な危険に合わせた避難計画を作れること","explanationKo":"河川の氾濫に備えて地域ごとに対策すること에는 身近な危険に合わせた避難計画を作れること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3541","prompt":"「輸送」の読み方として最も適切なものを選びなさい。","options":["ゆそう","じんめい","むげん","ぶんたい"],"answer":"ゆそう","explanationKo":"「輸送」는 「ゆそう」라고 읽는다. 뜻은 수송; 사람이나 물자를 다른 장소로 운반함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3542","prompt":"「油断」の読み方として最も適切なものを選びなさい。","options":["ふごう","せっきん","もんどう","ゆだん"],"answer":"ゆだん","explanationKo":"「油断」는 「ゆだん」라고 읽는다. 뜻은 방심; 주의를 게을리함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-3543","prompt":"「用語」の読み方として最も適切なものを選びなさい。","options":["つうよう","たいりつ","ようご","めやす"],"answer":"ようご","explanationKo":"「用語」는 「ようご」라고 읽는다. 뜻은 용어; 특정 분야에서 정해진 의미로 쓰는 말이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-3544","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n報告書の（　）を冒頭にまとめ、結論を分かりやすくした。","options":["利害","要旨","増減","連合"],"answer":"要旨","explanationKo":"문맥상 「要旨」가 가장 자연스럽다. 요지; 내용의 중심이 되는 중요한 뜻라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-3545","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n補助金の（　）は規則によって厳しく限定されている。","options":["用途","損得","要領","診断"],"answer":"用途","explanationKo":"문맥상 「用途」가 가장 자연스럽다. 용도; 물건이나 자금을 사용하는 목적라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-3546","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請（　）を確認し、必要な書類を期限内に提出した。","options":["消化","断定","標準","要領"],"answer":"要領","explanationKo":"문맥상 「要領」가 가장 자연스럽다. 요령; 일의 핵심이나 처리 방법; 핵심 내용라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-3547","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n停電に備えて（　）の電源と通信手段を確保している。","options":["方針","例外","予備","普及"],"answer":"予備","explanationKo":"문맥상 「予備」가 가장 자연스럽다. 예비; 필요할 때를 대비해 미리 준비함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-3548","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n洪水対策は自治体の境界ではなく（　）全体で考える必要がある。","options":["分類","流域","要領","推定"],"answer":"流域","explanationKo":"문맥상 「流域」가 가장 자연스럽다. 유역; 한 강으로 물이 모이는 지역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-3549","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n利用者の増加に対応するため、（　）の窓口を設置した。","options":["臨時","調整","住居","身分"],"answer":"臨時","explanationKo":"문맥상 「臨時」가 가장 자연스럽다. 임시; 정해진 때가 아닌 필요에 따라 일시적으로 마련함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-3550","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n原則を示すだけでなく、どの条件を（　）とするかも明記した。","options":["法則","複数","成立","例外"],"answer":"例外","explanationKo":"문맥상 「例外」가 가장 자연스럽다. 예외; 일반 원칙이나 규칙에 들어맞지 않는 것라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3551","prompt":"「二つ以上の組織や集団が共通の目的で結び付くこと。」という意味に最も近い語を選びなさい。","options":["流域","製作","連合","方針"],"answer":"連合","explanationKo":"「連合」의 핵심 의미는 연합; 둘 이상의 조직이나 집단이 결합함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3552","prompt":"「広く行き渡り、多くの人に使われるようになること。」という意味に最も近い語を選びなさい。","options":["人命","普及","申請","貯蔵"],"answer":"普及","explanationKo":"「普及」의 핵심 의미는 보급; 널리 퍼져 일반적으로 사용됨이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3553","prompt":"「数が二つ以上であること。」という意味に最も近い語を選びなさい。","options":["複数","符号","接近","未満"],"answer":"複数","explanationKo":"「複数」의 핵심 의미는 복수; 둘 이상의 수나 대상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3554","prompt":"「意味や情報を表すために用いる記号。」という意味に最も近い語を選びなさい。","options":["編集","成分","目安","符号"],"answer":"符号","explanationKo":"「符号」의 핵심 의미는 부호; 의미나 정보를 나타내는 기호이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-3555","prompt":"「事件や危険が起こりそうで、不安なさま。」という意味に最も近い語を選びなさい。","options":["敬う","縛る","物騒","測定"],"answer":"物騒","explanationKo":"「物騒」의 핵심 의미는 위험하고 불안함; 사건이 일어날 듯 흉흉함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','grammar',1,'〜ならいざ知らず','{"pattern":"〜ならいざ知らず","meaningKo":"〜라면 몰라도","explanation":"〜ならいざ知らず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"試作品ならいざ知らず、販売品でこの欠陥は許されない。","ko":"문맥에서 〜라면 몰라도의 의미로 쓰였다."},{"ja":"一度ならいざ知らず、同じ誤りを繰り返すのは問題だ。","ko":"이 문장도 〜라면 몰라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','grammar',2,'〜とあっては','{"pattern":"〜とあっては","meaningKo":"〜라는 상황이라면","explanation":"〜とあっては는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"安全にかかわる問題とあっては、見過ごすわけにはいかない。","ko":"문맥에서 〜라는 상황이라면의 의미로 쓰였다."},{"ja":"住民の生活が脅かされるとあっては、行政も対応を急ぐだろう。","ko":"이 문장도 〜라는 상황이라면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n試作品（　）、販売品でこの欠陥は許されない。","options":["〜に基づいて","〜を通じて","〜てならない","〜ならいざ知らず"],"answer":"〜ならいざ知らず","explanationKo":"문맥상 〜라면 몰라도를 나타내는 「〜ならいざ知らず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n安全にかかわる問題（　）、見過ごすわけにはいかない。","options":["〜にとどまらず","〜とみえて","〜とあっては","〜に沿って"],"answer":"〜とあっては","explanationKo":"문맥상 〜라는 상황이라면를 나타내는 「〜とあっては」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの結果（　）、計画全体が成功したとは断定できない。","options":["〜ものを","〜をもって","〜に応じて","〜のみならず"],"answer":"〜をもって","explanationKo":"문맥상 〜을 기해; 〜으로써를 나타내는 「〜をもって」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-01-20','reading',1,'標本の偏りを疑う','{"passage":"一部の事例から全体の特徴を推定することには、全員を調べずに傾向を把握できることという利点がある。しかし、集めやすい対象だけでは全体と異なる結論になることに注意しなければ、その利点を生かせない。目的と対象を明らかにし、実施後に結果を検証できる形にしておく必要がある。したがって、誰が標本に入りにくいかを確認して補正することが重要なのである。","questions":[{"prompt":"「標本の偏りを疑う」について筆者が最も重視していることは何か。","options":["誰が標本に入りにくいかを確認して補正すること","最初の方法を変更しないこと","対象を定めずに広く実施すること","結果より作業量だけを評価すること"],"answer":"誰が標本に入りにくいかを確認して補正すること","explanationKo":"본문에서는 誰が標本に入りにくいかを確認して補正すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["集めやすい対象だけでは全体と異なる結論になること","目的を明らかにすると利点が失われること","結果を検証すると作業を続けられないこと","対象を定めると情報がすべて失われること"],"answer":"集めやすい対象だけでは全体と異なる結論になること","explanationKo":"주의할 점은 集めやすい対象だけでは全体と異なる結論になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["全員を調べずに傾向を把握できること","実施後の確認は必要ない","目的は曖昧な方がよい","一つの方法をすべての対象に適用すべきだ"],"answer":"全員を調べずに傾向を把握できること","explanationKo":"一部の事例から全体の特徴を推定すること에는 全員を調べずに傾向を把握できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
